# ---------------------------------------------------------------------------
# Paths and defaults
# ---------------------------------------------------------------------------
CONFIG_FILE = Path(os.environ.get('ISEMON_CONFIG', '/etc/isemon/config.json'))
STATE_DIR = Path(os.environ.get('ISEMON_STATE', '/var/lib/isemon'))
DB_FILE = STATE_DIR / 'isemon.db'
BACKUP_DIR = STATE_DIR / 'backups'
# The nightly dump, made by whichever engine's own program belongs to the
# database in use: pg_dump, mariadb-dump, or - on the file - SQLite's own
# backup, which is the file. Kept apart from the copies above because they
# are two different things kept for two different reasons: a copy goes back
# into any of the three engines and is what carries an installation from one
# to another, a dump goes back into the engine it came off and is what a
# database administrator already knows what to do with.
DUMP_DIR = STATE_DIR / 'dumps'
RUN_DIR = Path('/run/isemon')
TOKEN_FILE = RUN_DIR / 'api-token'
LOG_DIR = Path('/var/log/isemon')
SERVICE_USER = 'isemon'

SSH_CONNECT_TIMEOUT = 10
SSH_RUN_TIMEOUT = 45


# The roles an account may have (1.10.165). `banadmin` reads everything as
# `readonly` does, and may also ban, let back in and put the lists on the
# router - nothing else: no setting, no account, no taking ours off the
# router, no letting everybody in at once.
ROLES_ALL = ('fulladmin', 'banadmin', 'readonly')
ROLE_WORDS = {'fulladmin': 'full admin', 'banadmin': 'ban admin', 'readonly': 'read only'}

