def nps_word(table, said):
    """A coded value in words, with the number it was written as."""
    said = str(said or '').strip()
    if not said:
        return ''
    words = table.get(said)
    return '%s (%s)' % (words, said) if words else said


def nps_seconds(said):
    """Seconds, as somebody would say them: 28800 is 8 h."""
    try:
        n = int(str(said).strip())
    except ValueError:
        return str(said or '')
    if n < 120:
        return '%d s' % n
    if n < 7200:
        return '%d min' % (n // 60) + (' %d s' % (n % 60) if n % 60 else '')
    return '%d h' % (n // 3600) + (' %d min' % (n % 3600 // 60) if n % 3600 // 60 else '')


def nps_bytes(said):
    try:
        return human_size(int(str(said).strip()))
    except ValueError:
        return str(said or '')


def nps_class(said):
    """What NPS put in the Class it stamped on a request and its answer.

    `311 1 172.29.136.9 07/23/2026 07:23:32 810669`: Microsoft's number, the
    address of the NPS server that answered, when its service last started,
    and a counter of its own. The two in the middle are worth a line each.
    """
    m = re.match(r'^311 \d+ (\S+) (\d\d/\d\d/\d{4} \d\d:\d\d:\d\d) (\d+)$',
                 str(said or '').strip())
    if not m:
        return None
    return m.group(1), m.group(2), m.group(3)


def nps_hex_text(said):
    """`0x014D555A4142524548` -> `MUZABREH`: a value NPS wrote as hex, in text.

    MS-CHAP-Domain is one byte of identifier and then the domain; any other
    hex value that turns out to be text is shown as the text.
    """
    said = str(said or '').strip()
    if not re.match(r'^0x[0-9A-Fa-f]{4,}$', said) or len(said) % 2:
        return ''
    try:
        raw = bytes.fromhex(said[2:])
    except ValueError:
        return ''
    text = raw[1:] if raw[:1] < b' ' else raw
    try:
        text = text.decode('ascii')
    except UnicodeDecodeError:
        return ''
    return text if text and text.isprintable() else ''


# Every coded column, and the words it is shown with in an opened record.
NPS_IN_WORDS = (
    ('Packet-Type', 'Packet', NPS_PACKET),
    ('Client-Vendor', 'Make of the device', NPS_VENDOR),
    ('Framed-Protocol', 'Framed protocol', NPS_FRAMED_PROTOCOL),
    ('Provider-Type', 'Checked by', NPS_PROVIDER),
    ('Tunnel-Type', 'Tunnel type', NPS_TUNNEL_TYPE),
    ('Tunnel-Medium-Type', 'Tunnel medium', NPS_TUNNEL_MEDIUM),
    ('Termination-Action', 'At the session\u2019s end', NPS_TERMINATION_ACTION),
    ('Acct-Status-Type', 'Accounting', NPS_ACCT_STATUS),
    ('Acct-Authentic', 'Accounting authenticated by', NPS_ACCT_AUTHENTIC),
    ('Acct-Terminate-Cause', 'Why the session ended', NPS_ACCT_TERMINATE),
    ('MS-Acct-Auth-Type', 'Authentication (accounting)', NPS_AUTH_TYPE),
    ('MS-Acct-EAP-Type', 'EAP type (accounting)', NPS_EAP_TYPE),
)


def nps_words_for(got):
    """Everything coded in one request-and-answer, in words, in order."""
    out = collections.OrderedDict()
    for column, name, table in NPS_IN_WORDS:
        if got.get(column):
            out[name] = nps_word(table, got[column])
    for column, name in (('Session-Timeout', 'Session limit'),
                         ('Idle-Timeout', 'Idle limit'),
                         ('Acct-Session-Time', 'Session lasted'),
                         ('Acct-Delay-Time', 'Accounting sent late by')):
        if got.get(column):
            out[name] = nps_seconds(got[column])
    for column, name in (('Acct-Input-Octets', 'Received'),
                         ('Acct-Output-Octets', 'Sent')):
        if got.get(column):
            out[name] = nps_bytes(got[column])
    said = nps_class(got.get('Class'))
    if said:
        out['Answered by NPS at'] = said[0]
        out['NPS service running since'] = said[1]
    for column, name in (('MS-CHAP-Domain', 'Domain (MS-CHAP)'),
                         ('Class', 'Class, as text')):
        text = nps_hex_text(got.get(column))
        if not text and column == 'MS-CHAP-Domain':
            # ...which NPS writes as text as well, on some packets: `\DOMAIN`.
            text = str(got.get(column) or '').strip().lstrip('\\')
        if text:
            out[name] = text
    for column, name in (('Calling-Station-Id', 'The machine\u2019s MAC'),
                         ('Called-Station-Id', 'The switch\u2019s or access point\u2019s MAC')):
        said = str(got.get(column) or '')
        mac = mac_written(said.split(':', 1)[0] if said.count(':') == 1 else said)
        if mac and mac != said:
            out[name] = mac
    return out


