        # index holds only the ones that do.
        ('win_logon', {
            True: 'CREATE INDEX IF NOT EXISTS win_logon ON win_events '
                  "(by_logon, ts) WHERE by_logon <> ''",
            False: 'CREATE INDEX IF NOT EXISTS win_logon ON win_events '
                   '(by_logon, ts)'}),

        ('passed_acl', 'CREATE INDEX IF NOT EXISTS passed_acl ON passed (acl, ts)'),
        ('passed_tkey', 'CREATE INDEX IF NOT EXISTS passed_tkey ON passed (tkey, ts)'),
        # "Who has been trying hardest in the last day" is a count per
        # address over a slice of time. With an index on the time alone,
        # SQLite would rather walk the whole table in address order than
