        # at the table at all.
        ('failed_ts_ip', 'CREATE INDEX IF NOT EXISTS failed_ts_ip ON failed (ts, ip)'),
        ('passed_ts_ip', 'CREATE INDEX IF NOT EXISTS passed_ts_ip ON passed (ts, ip)'),
        # Filtering by country, and counting how many rows each country has.
        # Both are the same index read two ways: the country first so one
        # country is a slice rather than a search, the time after it so the
        # slice comes back newest-first without a sort.
        ('failed_country_ts',
         'CREATE INDEX IF NOT EXISTS failed_country_ts ON failed (country, ts)'),
        ('passed_country_ts',
         'CREATE INDEX IF NOT EXISTS passed_country_ts ON passed (country, ts)'),
        ('blocked_log_ip', 'CREATE INDEX IF NOT EXISTS blocked_log_ip ON blocked_log (ip)'),
        # The ban history is let go of by when each ban ENDED (`tidy_older`
        # with column='ended'), and there was no index on that: every pass
        # behind the loop looked for the edge of a stride by sorting the
        # whole table, and each strided delete walked it again. (1.10.178)
        ('blocked_log_ended',
         {False: 'CREATE INDEX IF NOT EXISTS blocked_log_ended ON blocked_log (ended)',
          True: 'CREATE INDEX IF NOT EXISTS blocked_log_ended ON blocked_log (ended) '
                'WHERE ended IS NOT NULL'}),
        # Which door a refused attempt knocked on - RADIUS for the VPN,
        # TACACS+ for a switch - read as a slice and counted as a walk of the
        # index, the same way the countries are.
        ('failed_protocol_ts',
         'CREATE INDEX IF NOT EXISTS failed_protocol_ts ON failed (protocol, ts)'),
        # One tab is one slice of this index, and the counts on the tabs are
        # one walk of it.
        ('failed_kind_ts', 'CREATE INDEX IF NOT EXISTS failed_kind_ts ON failed (kind, ts)'),
        ('passed_kind_ts', 'CREATE INDEX IF NOT EXISTS passed_kind_ts ON passed (kind, ts)'),
        ('failed_mac_ts', 'CREATE INDEX IF NOT EXISTS failed_mac_ts ON failed (mac, ts)'),
        # One device picked in the filter, newest first (1.10.184): without
        # it the list walked the time index backwards, every row of every
        # other device read and thrown away, and for a device that is rarely
        # in the logs the count under the list read the whole table.
        ('failed_device_ts', 'CREATE INDEX IF NOT EXISTS failed_device_ts ON failed (device, ts)'),
        ('passed_device_ts', 'CREATE INDEX IF NOT EXISTS passed_device_ts ON passed (device, ts)'),
        # The ban history in the order it is shown - newest change first -
        # read off an index rather than the whole table sorted. (1.10.184)
        ('blocked_log_order',
         {False: '', True: 'CREATE INDEX IF NOT EXISTS blocked_log_order ON blocked_log '
                           '((COALESCE(ended, ts)) DESC, ts DESC, ip DESC)'}),
        # Which names an address tried, and which addresses tried a name.
        # Both are counts over everything ever recorded, and both were being
        # answered by reading the rows themselves: the index over (ip, ts)
        # finds an address's rows in a moment and then has to fetch each one
        # to see the name on it, which on a busy address is tens of thousands
        # of scattered reads. With the name in the index the count never
        # leaves it - fifteen times quicker on a database of a million, and
        # it is the difference between the Banned page taking four seconds
        # and taking a tenth of one.
        ('failed_ip_user',
         'CREATE INDEX IF NOT EXISTS failed_ip_user ON failed (ip, username)'),
        ('failed_user_ip',
         'CREATE INDEX IF NOT EXISTS failed_user_ip ON failed (username, ip)'),
        # ...and the same for the sign-ins, which the box that finds anything
        # reads on every keystroke. Without it that half of the search had to
        # fetch a row for every name it matched - a walk of the whole table
        # on a database of millions, while the refusals beside it never left
