        # engines that have them; MariaDB has none, and goes on as before.
        ('win_account_lc', {False: '', True: 'CREATE INDEX IF NOT EXISTS win_account_lc '
                                             'ON win_events (LOWER(account), ts)'}),
        # ...and a machine, pressed on a card or asked for by name: the
        # same fold, and the same walk of the window without it. (1.10.178)
        ('win_machine_lc', {False: '', True: 'CREATE INDEX IF NOT EXISTS win_machine_lc '
                                             'ON win_events (LOWER(machine), ts)'}),
        # ...and the same for a name pressed on either list of the
        # authentications, `LOWER(username) = ?`: a second, counting it,
        # over a year of three million refusals; a few milliseconds with
        # this. (1.10.159)
        ('failed_user_lc', {False: '', True: 'CREATE INDEX IF NOT EXISTS failed_user_lc '
                                             'ON failed (LOWER(username), ts)'}),
        ('passed_user_lc', {False: '', True: 'CREATE INDEX IF NOT EXISTS passed_user_lc '
                                             'ON passed (LOWER(username), ts)'}),
        # One address, two ways. The box that finds anything is given a
        # prefix - a seek down this and a short walk - and everything a
        # suggestion shows is in the index, so it never touches the table:
