    # Which of the three layers a value is standing on, in the words the page
    # shows. The same three the original used, because the question a person
    # has in front of a setting is always "why does it say that".
    WHERE_FROM = {
        'saved': 'saved on this dashboard — wins over config.json',
        'file': 'from config.json',
        'default': 'the built-in default (not in config.json)',
    }

