def cmd_directory(args, pal, store):
    """Is the directory there, does it answer, and are the groups real."""
    session = cli_session(store)
    status, data = api_call('/api/directory', 'POST', {'check': True}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    pal.title('Active Directory')
    pal.kv('server', '%s:%d' % (data.get('host') or '-', data.get('port') or 0))
    pal.kv('how', data.get('tls') or 'none')
    pal.kv('certificate', 'not used' if (data.get('tls') or 'none') == 'none'
           else (pal.ok_text('checked') if data.get('verify')
                 else pal.bad_text('NOT checked')))
    pal.kv('where it looks', data.get('base') or '-')
    pal.blank()
    for one in data.get('steps') or []:
        if one['ok']:
            pal.good('  %s' % one['what'])
        else:
            pal.bad('  %s' % one['what'])
        if one.get('said'):
            pal.note('      %s' % one['said'])
    pal.blank()
    if data.get('ok'):
        pal.good('the directory answered everything')
    else:
        pal.bad('the directory did not answer everything; the step above says which')
    pal.note('  isemon --directory-groups        every group it holds')
    pal.note('  isemon --set directory_admin_group="CN=...;CN=..."   separated by SEMICOLONS,')
    pal.note('  because a distinguished name is full of commas')
    return 0 if data.get('ok') else 1


def cmd_directory_groups(args, pal, store):
    """The groups, so a role can be pointed at one without typing it."""
    session = cli_session(store)
    status, data = api_call('/api/directory', 'POST',
                            {'groups': True, 'like': args.directory_groups or ''},
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    groups = data.get('groups') or []
    pal.title('%s group(s) in the directory' % num_words(len(groups)))
    if not groups:
        pal.note('  Nothing under that base, or the base is not where the groups live.')
        return 0
    print_table(pal, ['name', 'what it is for', 'distinguished name'],
                [[(g['name'], pal.c_hi), (g['says'] or '')[:40], (g['dn'], pal.dim)]
                 for g in groups], indent=2)
    pal.note('\n  Put one in a role with, for example:')
    pal.note('    isemon --set directory_admin_group="%s"' % groups[0]['dn'])
    pal.note('  More than one is separated by a SEMICOLON, never a comma.')
    return 0


def cmd_users(args, pal, store):
    rows = store.users()
    if as_json(args, {'users': rows}):
        return 0
    pal.title('%d account(s)' % len(rows))
    print_table(pal, ['name', 'role', 'state', 'made', 'last signed in', 'note'],
                [[u['name'], u['role'],
                  'off' if u['disabled'] else ('must change' if u.get('must_change') else 'on'),
                  short_stamp(u['made']), stamp(u['last_in']) if u['last_in'] else 'never',
                  (u.get('note') or '')[:30]] for u in rows], indent=2,
                paint=lambda n, i, cell: (
                    pal.c_hi if i == 0 else
                    (pal.c_info if i == 1 and cell == 'fulladmin' else
                     ({'on': pal.c_ok, 'off': pal.c_bad}.get(cell, pal.c_warn) if i == 2
                      else (pal.dim if i in (3, 4) else None)))))
    if not rows:
        pal.note('  Nobody can open the dashboard. Make somebody:')
        pal.note('    isemon --add-user yourname --role fulladmin')
    return 0


def ask_password(pal, twice=True):
    first = getpass.getpass('    New password: ')
    if len(first) < 8:
        pal.bad('a password is at least eight characters')
        return None
    if twice:
        again = getpass.getpass('    And again:    ')
        if first != again:
            pal.bad('those two are not the same')
            return None
    return first


def cmd_add_user(args, pal, store):
    # Making an account never changes one that is there (see `Daemon.add_user`).
    if store.user(str(args.add_user or '').strip().lower()):
        pal.bad('there is already an account called %s - to give it a new password: '
                'isemon --passwd %s' % (args.add_user, args.add_user))
        return 1
    password = args.password or os.environ.get('ISEMON_PASSWORD') or ask_password(pal)
    if not password:
        return 1
    role = args.role or 'readonly'
    if role not in Daemon.ROLES:
        pal.bad('a role is fulladmin, banadmin or readonly')
        return 1
    try:
        # ...and made to choose its own, where asked (1.10.200): --must-change
        # was taken and said nothing.
        store.put_user(args.add_user, password=password, role=role, by='command line',
                       note=args.note or '', must_change=bool(getattr(args, 'must_change', False)))
    except StorageError as e:
        pal.bad(str(e))
        return 1
    store.add_event('users', 'the account %s was made from the command line, as %s'
                    % (args.add_user, role), who='command line')
    pal.good('%s may now sign in, as %s' % (args.add_user, role))
    return 0


def cmd_passwd(args, pal, store):
    name = str(args.passwd).strip().lower()
    if not store.user(name):
        pal.bad('there is no account called %s' % name)
        return 1
    password = args.password or os.environ.get('ISEMON_PASSWORD') or ask_password(pal)
    if not password:
        return 1
    if len(password) < 8:
        pal.bad('a password is at least eight characters')
        return 1
    store.put_user(name, password=password, must_change=bool(args.must_change))
    store.drop_session(name=name)
    store.add_event('users', 'the password for %s was reset from the command line' % name,
                    who='command line')
    pal.good('the password for %s was changed; every sign-in of that account was ended' % name)
    return 0


def cmd_user_role(args, pal, store):
    name = str(args.set_role).strip().lower()
    role = args.role or ''
    if role not in Daemon.ROLES:
        pal.bad('--role is fulladmin, banadmin or readonly')
        return 1
    user = store.user(name)
    if not user:
        pal.bad('there is no account called %s' % name)
        return 1
    if user['role'] == 'fulladmin' and role != 'fulladmin' and not user.get('disabled') \
            and store.admin_count() <= 1:
        pal.bad('that is the only full administrator; make another one first')
        return 1
    store.put_user(name, role=role)
    store.add_event('users', '%s is now %s (command line)' % (name, role), who='command line')
    pal.good('%s is now %s' % (name, role))
    return 0


def cmd_erase(args, pal, store):
    """Erase the collected data, keeping everything anybody set up."""
    session = cli_session(store)
    groups = [g.strip().lower() for g in comma_list(args.erase) if g.strip()]
    if groups == ['list'] or not groups:
        pal.title('What can be erased')
        pal.note('  Accounts, settings and the whitelist are never in this list, and are never')
        pal.note('  touched by any of it.')
        print_table(pal, ['name', 'rows', 'what it is'],
                    [[g['key'], num_words(g['rows']), g['says'][:76]]
                     for g in store.erasable()], right=(1,), indent=2,
                    paint=lambda n, i, cell: (pal.c_key if i == 0 else
                                              (pal.c_hi if i == 1 else pal.dim)))
        pal.note('\n  Erase one or more with:  isemon --erase geo  ·  isemon --erase records,feeds')
        return 0
    known = list(store.ERASABLE)
    unknown = [g for g in groups if g not in known]
    if unknown:
        pal.bad('there is nothing called %s' % ', '.join(unknown))
        pal.note('  the ones there are: %s' % ', '.join(known))
        return 1
    had = {g['key']: g for g in store.erasable()}
    pal.title('About to erase')
    for key in groups:
        pal.bullet('%s \u2014 %s row(s)' % (pal.hi(had[key]['name']),
                                            num_words(had[key]['rows'])))
    pal.note('  accounts, settings and the whitelist are not touched')
    if not args.yes:
        try:
            said = input('  type "erase" to go ahead: ').strip().lower()
        except (EOFError, KeyboardInterrupt):
            said = ''
        if said != 'erase':
            pal.note('  nothing was erased')
            return 1
    status, data = api_call('/api/db/erase', 'POST',
                            {'groups': groups, 'tidy': True}, session=session)
    if status:
        if not need_daemon(pal, status, data):
            return 1
        return watch_job(pal, data['job'], session)
    # The daemon is not answering, and this is one of the things somebody does
    # precisely because it is not: a database too big to open.
    pal.note('  the daemon is not answering, so this goes straight to the database')
    gone = store.erase(groups)
    before, after = store.optimize()
    store.add_event('control', 'data was erased from the command line: %s'
                    % ', '.join(groups), 'warn', who='the command line')
    pal.good('erased %s' % ', '.join('%s (%s row(s))' % (k, num_words(v))
                                     for k, v in gone.items()))
    if after < before:
        pal.note('  the database went from %s to %s' % (human_size(before), human_size(after)))
    return 0


def cmd_switch_user(args, pal, store):
    """Switch an account off, or back on, from the command line.

    Straight to the database like the rest of the account commands, because
    the moment this is most needed - somebody has left, or an account is
    being misused - is a moment nobody wants to depend on the daemon
    answering.
    """
    off = bool(args.disable_user)
    name = str(args.disable_user or args.enable_user).strip().lower()
    user = store.user(name)
    if not user:
        pal.bad('there is no account called %s' % name[:32])
        pal.note('  isemon --users  lists them')
        return 1
    person = store.same_person(name)
    if off and any((store.user(n) or {}).get('role') == 'fulladmin'
                   and not (store.user(n) or {}).get('disabled') for n in person) \
            and store.admins_besides(person) < 1:
        pal.bad('that is the only full administrator there is')
        pal.note('  an account that is switched off cannot sign in to switch it back on,')
        pal.note('  so make another full administrator first:')
        pal.note('    isemon --add-user somebody --role fulladmin')
        return 1
    if bool(user.get('disabled')) == off:
        pal.note('  %s was already switched %s' % (name, 'off' if off else 'on'))
        return 0
    store.set_disabled(name, off)
    store.switch_same_person(name, off)
    ended = sum((store.drop_session(name=one) or 0) for one in store.same_person(name)) \
        if off else 0
    store.add_event('users', '%s was switched %s (command line)%s'
                    % (name, 'off' if off else 'on',
                       ' - %d sign-in(s) ended' % ended if ended else ''),
                    'warn' if off else 'info', who='the command line')
    if off:
        pal.good('%s is switched off and cannot sign in' % name)
        if ended:
            pal.note('  %d sign-in(s) of that account ended just now' % ended)
        pal.note('  everything it did is kept, and the account itself is still here:')
        pal.note('    isemon --enable-user %s   puts it back' % name)
    else:
        pal.good('%s can sign in again' % name)
        if user.get('must_change'):
            pal.note('  it will be asked to choose a new password at the next sign-in')
    return 0


def cmd_del_user(args, pal, store):
    name = str(args.del_user).strip().lower()
    user = store.user(name)
    if not user:
        pal.bad('there is no account called %s' % name)
        return 1
    if user['role'] == 'fulladmin' and not user.get('disabled') and store.admin_count() <= 1:
        pal.bad('that is the only full administrator; make another one first')
        return 1
    store.drop_user(name)
    store.add_event('users', 'the account %s was removed (command line)' % name,
                    who='command line')
    pal.good('%s is gone' % name)
    return 0


def cmd_database(args, pal, store):
    """Which database everything is kept in, and moving it to another."""
    what = str(args.database or 'show')
    want = db_config()
    name = want['engine']
    # --to names a different engine to work on than the one in use. It is
    # what makes the whole thing orderly: reach a server, set it up and
    # carry everything into it while the daemon carries on using what it
    # has, and switch over at the end, once there is something to switch to.
    if args.to and what in ('test', 'setup', 'move', 'empty'):
        want = dict(want, engine=str(args.to))
        if args.to == 'sqlite':
            want['path'] = str(DB_FILE)
        elif name == 'sqlite':
            # The db_ settings were written for the far side; db_config only
            # reads them when db_engine names a server, so read them here.
            want.update(db_config(dict(CONFIG, db_engine=str(args.to))))
        name = want['engine']
    if what == 'show':
        pal.title('The database')
        pal.kv('engine', '%s (%s)' % (ENGINE_WORDS.get(name, name), name))
        pal.kv('where', dialect_for(want).where())
        if getattr(store, 'trouble', ''):
            pal.bad('  it will not open: %s' % store.trouble)
            pal.note('  an empty one has been opened in its place, so that this can be')
            pal.note('  put right. Nothing is being read and nobody is being banned.')
        else:
            pal.kv('size', human_size(store.size()))
            got = store.db.execute('SELECT COUNT(*) AS n FROM failed').fetchone()['n']
            other = store.db.execute('SELECT COUNT(*) AS n FROM passed').fetchone()['n']
            pal.kv('holding', '%s failed attempt(s), %s login(s)'
                   % (num_words(got), num_words(other)))
        # The nightly one, and whether it will be this engine's own dump or
        # the portable copy that stands in when the client is not here.
        ready, why = store.dump_ready()
        rows = store.dumps()
        pal.kv('the nightly one', '%s, %s at most, at %s'
               % (ENGINE_DUMP_WORDS.get(name, 'a dump') if ready else 'a portable copy',
                  int(CONFIG.get('backup_keep') or 14), CONFIG.get('backup_at') or '03:30')
               if int(CONFIG.get('backup_daily') or 0) else 'switched off')
        if not ready:
            pal.note('  %s' % why)
        pal.kv('dumps kept', '%d in %s' % (len(rows), DUMP_DIR))
        pal.note('')
        for engine in ENGINES:
            if engine == 'sqlite':
                pal.note('  sqlite    always here: it is part of Python')
                continue
            ready, why = DIALECTS[engine].driver_ready()
            pal.note('  %-9s %s' % (engine, 'the driver is installed' if ready else why))
        pal.note('')
        pal.note('  the settings that say which one, and how to reach it, are the only')
        pal.note('  ones kept in %s rather than in the database:' % CONFIG_FILE)
        pal.note('    %s' % ', '.join(FILE_ONLY))
        return 0

    if what == 'test':
        pal.title('Reaching %s' % ENGINE_WORDS.get(name, name))
        got = db_try(want)
        if not got['ok']:
            pal.bad('  %s' % got['trouble'])
            if got.get('driver'):
                pal.note('  nothing was tried: without the driver there is nothing to try with')
            return 1
        pal.good('  %s' % got.get('where') or '')
        pal.kv('it says it is', got.get('version') or 'nothing about itself')
        pal.kv('tables there', '%d, %d of them ours' % (got['tables'], got['ours']))
        pal.kv('records', num_words(got['rows']))
        pal.kv('may this account write', 'yes' if got['writable'] else 'NO')
        return 0 if got['writable'] else 1

    if what == 'empty':
        # Throwing the far side away, so that a move can be tried again. Only
        # ever the far side: what is in use is reached through `store`, and
        # this refuses to be pointed at it.
        if not args.to:
            pal.bad('say which one: --database empty --to mariadb')
            return 1
        if same_database(want, store.engine):
            pal.bad('that is the database in use; this only ever empties the other one')
            pal.note('  to start the one in use again:  isemon --erase records')
            return 1
        got = db_try(want)
        if not got['ok']:
            pal.bad('  %s' % got['trouble'])
            return 1
        pal.title('Emptying %s' % dialect_for(want).where())
        pal.note('  %s record(s) in it, and everything else it holds: accounts, settings,'
                 % num_words(got['rows']))
        pal.note('  the whitelist, the lot. Nothing in the database in use is touched.')
        if not args.yes:
            try:
                if input('  type yes to go on: ').strip().lower() != 'yes':
                    pal.note('  nothing done')
                    return 1
            except (EOFError, KeyboardInterrupt):
                pal.note('  nothing done')
                return 1
        far = Storage(engine=want)
        try:
            gone = far.wipe()
        finally:
            far.close()
        pal.good('  %d table(s) thrown away; it is as good as new' % gone)
        pal.note('  now:  isemon --database move --to %s' % name)
        return 0

    if what == 'setup':
        if name == 'sqlite':
            pal.bad('there is nothing to set up: the file engine needs no server')
            return 1
        pal.title('Setting %s up' % ENGINE_WORDS.get(name, name))
        # Already there and this account gets in? Then nothing is made and
        # no administrator is asked for: what follows is the pass over the
        # tables, which is the upgrade check.
        first = db_try(want) if want.get('password') else {'ok': False}
        already = bool(first.get('ok') and first.get('writable'))
        fresh, done = '', []
        if already:
            pal.good('  the database and the account are already there')
        else:
            who = args.admin_user or input('  an administrator on that server: ').strip()
            word = args.admin_password
            if word is None:
                word = getpass.getpass('  its password: ')
            if not want.get('password'):
                fresh = db_password_made()
                want['password'] = fresh
            try:
                done = db_make(want, who, word)
            except Exception as e:
                pal.bad('  %s' % str(e).split(chr(10))[0][:200])
                return 1
            for one in done:
                pal.good('  made %s' % one)
            pal.note('  that administrator was used for this and written nowhere')
        # The address of what was just made, so nothing has to be typed twice.
        try:
            write_file_settings({'db_host': want['host'], 'db_port': want['port'],
                                 'db_name': want['name'], 'db_user': want['user'],
                                 'db_password': want['password'],
                                 'db_timeout_s': want.get('timeout') or 10})
        except Exception as e:
            pal.bad('  the address could not be saved: %s' % str(e).split(chr(10))[0][:160])
            return 1
        pal.good('  the address is saved in %s' % CONFIG_FILE)
        # The same pass this program makes on every start: build what is
        # missing, add the columns and indexes an older version never made,
        # and say what is still short.
        was_tables = set(first.get('table_names') or ())
        try:
            far = Storage(engine=want)
            try:
                ours = [t for t in Dialect.schema_tables(SCHEMA)
                        if t in set(far.dialect.tables(far.db))]
                fresh_tables = sorted(t for t in ours if t not in was_tables)
                short = far.missing_columns()
                indexes = sum(len(far.dialect.indexes(far.db, t)) for t in ours)
            finally:
                far.close()
        except Exception as e:
            pal.bad('  its tables could not be put right: %s'
                    % str(e).split(chr(10))[0][:160])
            return 1
        pal.kv('tables there', '%d, with %d index(es)' % (len(ours), indexes))
        if fresh_tables:
            pal.good('  made: %s' % ', '.join(fresh_tables))
        elif already:
            pal.good('  every table this version wants is there, with its columns and indexes')
        if short:
            pal.bad('  still missing: %s' % ', '.join(short))
        if fresh:
            pal.say()
            pal.title('The password made for %s' % want['user'])
            pal.note('  %s' % fresh)
            pal.note('  It is in %s and nowhere else. Keep a copy if you want one;'
                     % CONFIG_FILE)
            pal.note('  this is the only time it is printed.')
            pal.say()
        got = db_try(want)
        if got['ok']:
            pal.good('  and the account reaches it: %s' % (got.get('version') or ''))
        else:
            pal.bad('  but the account cannot reach it: %s' % got['trouble'])
            return 1
        pal.note('')
        pal.note('  nothing has moved yet. To carry everything across:')
        pal.note('    isemon --database move --to %s' % name)
        return 0

    # move: out of the database that is live now, into the one named by
    # --to using the settings for it. Which database is live does not change
    # here, and nothing that is here is touched - so a move that goes wrong
    # costs the time it took and nothing else.
    if getattr(store, 'trouble', ''):
        pal.bad('the database this is set to use will not open, so there is nothing to '
                'carry out of it')
        pal.note('  %s' % store.trouble)
        return 1
    if not args.to:
        pal.bad('say which engine to carry everything into: --database move --to mariadb')
        pal.note('  the db_ settings say where that one is; --database test --to mariadb')
        pal.note('  tries them without moving anything.')
        return 1
    if same_database(want, store.engine):
        pal.bad('that is the database everything is already in')
        return 1
    pal.title('Carrying everything into %s' % ENGINE_WORDS.get(name, name))
    got = db_try(want)
    if not got['ok']:
        pal.bad('  %s' % got['trouble'])
        return 1
    if not got['writable']:
        pal.bad('  that account may not write to it')
        return 1
    if got['rows']:
        pal.bad('  there are already %s record(s) in it' % num_words(got['rows']))
        pal.note('  moving into a database that is not empty would mix two installations,')
        pal.note('  so nothing has been touched. Empty it first, if it really is spare:')
        pal.note('    isemon --database empty --to %s' % name)
        return 1
    copy = store.backup(label='before-moving')
    pal.good('  a copy of what is here: %s' % copy)
    far = Storage(engine=want)
    try:
        far.restore(copy)
    except Exception as e:
        pal.bad('  it could not be carried across: %s' % str(e)[:160])
        return 1
    after = db_try(want)
    pal.good('  %s record(s) are now in %s'
             % (num_words(after['rows']), ENGINE_WORDS.get(name, name)))
    far.close()
    pal.note('')
    pal.note('  nothing about which database is live has changed yet. To use it:')
    pal.note('    isemon --set db_engine=%s' % name)
    pal.note('    systemctl restart isemon')
    pal.note('  what was here is untouched either way, and the copy above puts it back.')
    return 0


def cmd_settings(args, pal, store):
    if args.set:
        session = cli_session(store)
        want = {}
        for piece in args.set:
            if '=' not in piece:
                pal.bad('--set wants key=value, not %r' % piece)
                return 1
            key, _, value = piece.partition('=')
            # A secret by the environment, off the command line where `ps`
            # shows it (1.10.228): KEY=@env takes ISEMON_VALUE_KEY.
            if value.strip() == '@env':
                from_env = 'ISEMON_VALUE_' + key.strip().upper()
                if from_env not in os.environ:
                    pal.bad('%s=@env, and %s is not set: nothing was saved'
                            % (key.strip(), from_env))
                    return 1
                value = os.environ[from_env]
            # The old name of the NPS switch is the new one (1.10.194).
            key = 'ban_from_nps' if key.strip() == 'judge_nps_vpn' else key
            want[key.strip()] = value.strip()
        if getattr(store, 'trouble', ''):
            # The database this installation is set to will not open, so
            # there is no account to sign in with and no settings table to
            # write to. This is the one moment the setting that says where
            # the database is has to be changeable, so it goes straight into
            # config.json - which is where it lives anyway.
            return set_settings_directly(want, pal, store)
        status, data = api_call('/api/settings', 'POST', {'settings': want}, session=session)
        if status:
            if not need_daemon(pal, status, data):
                return 1
            pal.good(data.get('message') or 'saved')
            return 0
        # The daemon is not answering. That is the moment somebody most needs
        # to change a setting - a port that clashes, a log path that is wrong,
        # the blacklist switched off to get a machine back - so it is written
        # straight to the database instead. The running daemon, whenever there
        # is one again, notices and takes it up without a restart.
        return set_settings_directly(want, pal, store)
    saved = store.settings_saved()
    if as_json(args, {'settings': {k: CONFIG.get(k) for k in sorted(DEFAULTS)
                                   if k not in SECRET_KEYS},
                      'saved_in_db': sorted(saved), 'file_only': list(FILE_ONLY),
                      'database': dialect_for(db_config()).where(),
                      'engine': db_config()['engine'], 'file': str(CONFIG_FILE)}):
        return 0
    pal.title('Settings (saved in %s)' % dialect_for(db_config()).where())
    rows = []
    for key in sorted(DEFAULTS):
        value = CONFIG.get(key)
        if key in SECRET_KEYS:
            value = secret_shown(value)
        if isinstance(value, list):
            value = ', '.join(str(v) for v in value)
        rows.append([key, str(value)[:48],
                     'config.json' if key in FILE_ONLY
                     else ('saved here' if key in saved
                           else ('config.json' if key in FILE_KEYS else 'default'))])
    print_table(pal, ['setting', 'value', 'from'], rows, indent=2,
                paint=lambda n, i, cell: (pal.c_key if i == 0 else
                                          (pal.c_hi if i == 1 else
                                           (pal.c_ok if cell == 'saved here'
                                            else (pal.c_info if cell == 'config.json'
                                                  else pal.dim)))))
    pal.note('\n  Change one with:  isemon --set block_tries=8 --set block_window_min=15')
    pal.note('  Everything saved lives in the database; %s is still read, and what is'
             % CONFIG_FILE)
    pal.note('  saved wins over it. Put a setting back to what the file says and it stops')
    pal.note('  being saved at all.')
    return 0


def set_settings_directly(want, pal, store):
    """Write settings into the database without the daemon's help."""
    fresh = dict(CONFIG)
    changed = []
    try:
        for key, value in want.items():
            value = check_setting(key, value)
            if fresh.get(key) != value:
                changed.append(key)
            fresh[key] = value
        check_settings_together(fresh)
    except ValueError as e:
        pal.bad(str(e))
        return 1
    if not changed:
        pal.note('  nothing was different')
        return 0
    # Which database this is, and how to reach it, goes into config.json and
    # nowhere else - the same rule the dashboard follows, for the same
    # reason: a database cannot hold the address of itself.
    into_file = [k for k in changed if k in FILE_ONLY]
    if into_file:
        write_file_settings({k: fresh[k] for k in into_file})
        FILE_CONFIG.update({k: fresh[k] for k in into_file})
    rest = [k for k in changed if k not in FILE_ONLY]
    put = {k: fresh[k] for k in rest if fresh[k] != FILE_CONFIG.get(k)}
    drop = [k for k in rest if fresh[k] == FILE_CONFIG.get(k)]
    # Not into the empty database that is standing in for one that would not
    # open: what is written there is thrown away the moment the real one is
    # back, and a setting somebody watched being accepted and then lost is
    # worse than one that was refused.
    standing_in = bool(getattr(store, 'trouble', ''))
    partly = False
    if (put or drop) and not standing_in:
        store.settings_write(put, drop, by='the command line')
    elif put or drop:
        pal.bad('  %s could not be saved: they live in the database, and the database '
                'this is set to use will not open' % ', '.join(sorted(put) + sorted(drop)))
        # Only what went into the file was saved (1.10.198): "saved" and a
        # nought said after that refusal were not true.
        if not into_file:
            return 1
        changed = list(into_file)
        drop = []
        partly = True
    if not standing_in:
        try:
            store.add_event('settings', 'changed: %s' % ', '.join(sorted(changed)),
                            who='the command line')
        except sqlite3.Error:
            pass
    pal.good('%d setting(s) saved' % len(changed))
    pal.note('  (written here rather than through the daemon, which either is not '
             'answering or has no database to write to)')
    for key in sorted(changed):
        pal.note('    %s = %s' % (key, secret_shown(fresh[key]) if key in SECRET_KEYS
                                  else fresh[key]))
    if drop:
        pal.note('    %s now follow %s again' % (', '.join(sorted(drop)), CONFIG_FILE))
    if into_file:
        pal.note('    %s went into %s, which is where the address of the database lives'
                 % (', '.join(sorted(into_file)), CONFIG_FILE))
    # Exit 1 where the database's part was not saved (1.10.198).
    return 1 if partly else 0


def cmd_rescan(args, pal, store):
    """Go back over every log and apply what the records earn.

    The daemon will not ban for something that happened longer ago than
    `judge_max_age_h`, which is right every day but the first. This is the
    first day: read it all, weigh it all, and keep out whatever earned it.
    """
    session = cli_session(store)
    try:
        only = log_modules_named(getattr(args, 'logs', '') or '')
    except ValueError as e:
        pal.title('Going back over the logs')
        pal.bad('  there is no log called %s' % e)
        pal.note('  the ones there are: %s'
                 % ', '.join('%s (%s)' % (k, w) for k, w in LOG_MODULES))
        return 2
    if only:
        pal.title('Going back over %s' % ', '.join(only))
        pal.note('  Only these are read, from the beginning, and what is already here is')
        pal.note('  left exactly as it is: a record is stored under its own id, so reading')
        pal.note('  a file again adds what was missing and nothing else.')
        if 'ise' not in only and 'nps' in only and 'nps-vpn' in judged_doors():
            pal.note('  Of these, only the VPN through NPS is judged: it is weighed afterwards,')
            pal.note('  and an address that earned a ban is banned.')
        elif 'ise' not in only:
            pal.note('  Nothing in these is ever judged, so nothing is weighed and nothing')
            pal.note('  can be banned by this.')
        if 'fwlog' in only:
            pal.note('  The firewall\u2019s log: every day still in its folder is read, oldest')
            pal.note('  first. A line already here is left alone and counted once - so this')
            pal.note('  fills in what is missing (older days, a gap while the daemon was')
            pal.note('  stopped) and leaves the counted cards of the rest as they were.')
            pal.note('  To count everything again from scratch:  isemon --erase firewall')
            if not int(CONFIG.get('fwlog_keep_allowed', 1) or 0):
                pal.warn('  the sessions it let through are not kept as rows here')
                pal.note('  (fwlog_keep_allowed), so read again they would be counted again:')
                pal.note('  erase the firewall\u2019s log first, which reads it again by itself.')
                return 1
        if set(only) & set(ZONELESS_LOGS) - {'fwlog'}:
            pal.note('  These logs carry no zone of their own. If this machine\u2019s zone')
            pal.note('  has been CHANGED since they were last read, the same lines arrive')
            pal.note('  again at the new time as well as the old - erase that module\u2019s')
            pal.note('  records first where that is what you are putting right.')
        status, data = api_call('/api/rescan', 'POST',
                                {'days': args.days or 0, 'read_files': True,
                                 'logs': ','.join(only)}, session=session)
        if not need_daemon(pal, status, data):
            return 1
        return watch_job(pal, data['job'], session)
    pal.title('Going back over every log')
    pal.note('  Every failure already recorded, and every one still in the files, weighed')
    pal.note('  against the settings as they stand. Nothing is un-banned and nothing is')
    pal.note('  banned twice; an address the whitelist covers is left alone.')
    status, data = api_call('/api/rescan', session=session)
    if need_daemon(pal, status, data):
        held = (data.get('records') or {})
        pal.note('\n  %s failed attempt(s) are recorded; the rule is %s, and a block lasts %s'
                 % (num_words(held.get('rows') or 0), data.get('trigger') or '?',
                    data.get('lengths') or '?'))
        # Every log switched on is read (1.10.204), whatever kind it is.
        if data.get('logs') and not args.no_reread:
            pal.note('  Read from the beginning: %s'
                     % ', '.join(str(one.get('words') or one.get('log')) for one in data['logs']))
        if not data.get('on'):
            pal.bad('  the blacklist is switched off, so this would ban nothing')
            return 1
    status, data = api_call('/api/rescan', 'POST',
                            {'days': args.days or 0, 'read_files': not args.no_reread,
                             'logs': str(getattr(args, 'logs', '') or '')},
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    return watch_job(pal, data['job'], session)


def cmd_ptr_fill(args, pal, store):
    """Go back and ask what every address already recorded is called.

    The daemon asks about an address when a record arrives from it and when
    a page carrying it is drawn, so everything since it was switched on has
    an answer and nothing from before it does. This is the pass that goes
    back over the rest. It is one job, it can be left to run, and it asks at
    the same handful a second as everything else - a year of a busy site is
    tens of thousands of questions and there is no hurry about any of them.
    """
    session = cli_session(store)
    pal.title('Looking up the names behind the addresses')
    status, data = api_call('/api/ptr', 'POST', {'missing': True}, session=session)
    if need_daemon(pal, status, data):
        missing = data.get('missing') or 0
        if not missing:
            pal.good('  every address in the records already has an answer')
            return 0
        pal.note('  %s address(es) have no name written down yet' % num_words(missing))
    status, data = api_call('/api/ptr', 'POST',
                            {'fill': True, 'days': args.days or 0}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    return watch_job(pal, data['job'], session)


def cmd_ptr(args, pal, store):
    """One address, asked of every name server in turn.

    Every one of them, rather than stopping at the first with an answer:
    what somebody typing this is usually doing is working out which server
    holds which zone, and a server that has the zone and one that has never
    heard of the address look exactly alike from the outside.
    """
    session = cli_session(store)
    status, data = api_call('/api/ptr', 'POST', {'try': args.ptr}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    if data.get('trouble'):
        pal.bad('  %s' % data['trouble'])
        return 1
    pal.title('What %s is called' % data.get('ip'))
    pal.note('  asked for %s' % data.get('question'))
    # A line per server, in the order they were asked, with the mark at the
    # front rather than in the middle of the line: this is read down the
    # left edge - which server answered - and not across.
    for one in data.get('asked') or []:
        words = one.get('name') or one.get('trouble') or one.get('says') or '-'
        line = '%-26s %-46s %5d ms' % (one.get('server') or '?', words[:46], one.get('ms') or 0)
        if one.get('name'):
            pal.good(line)
        elif one.get('trouble'):
            pal.bad(line)
        else:
            pal.note('  ' + line)
    if data.get('name'):
        pal.say('')
        pal.good('%s is %s, said by %s' % (data.get('ip'), data['name'], data.get('where')))
    else:
        pal.say('')
        pal.note('  no server in the list has a name for %s' % data.get('ip'))
    return 0


def cmd_ios_acl(args, pal, store):
    """The addresses out for good, as an access list, on standard output.

    Written to be redirected into a file and pasted into a router. Nothing
    but the access list goes to standard output, so `isemon --ios-acl > acl`
    is a file with nothing to trim off either end; anything worth saying
    about it is said on standard error.
    """
    session = cli_session(store)
    status, data = api_call('/api/blocked/ios?family=%s' % (args.ios_acl or 'ipv4'),
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    sys.stdout.write(data.get('text') or '')
    sys.stderr.write('%s range(s) and %s single address(es) kept out for good%s\n'
                     % (num_words(data.get('ranges') or 0),
                        num_words(data.get('singles') or 0),
                        (', and %s of the other family left out'
                         % num_words(data['skipped'])) if data.get('skipped') else ''))
    return 0


def cmd_mikrotik(args, pal, store):
    session = cli_session(store)
    if args.sync:
        status, data = api_call('/api/mikrotik', 'POST', {'sync': True}, session=session)
        if not need_daemon(pal, status, data):
            return 1
        return watch_job(pal, data['job'], session)
    if args.purge:
        status, data = api_call('/api/mikrotik', 'POST', {'purge': True, 'which': args.purge},
                                session=session)
        if not need_daemon(pal, status, data):
            return 1
        return watch_job(pal, data['job'], session)
    status, data = api_call('/api/blocked/router', session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    # The one question somebody types this to answer: is what the router is
    # carrying what this says it should be carrying. It goes first, because
    # reading it off the table underneath is work.
    state = data.get('state') or {}
    walls = data.get('firewalls') or []
    if len(walls) > 1:
        # Two of them. Whether they are saying the same thing comes first,
        # because it is the one thing a pair is for and the one thing the
        # table below cannot show.
        pal.title('The pair')
        agree = data.get('agree')
        pal.kv('both carrying the same',
               pal.ok_text('yes') if agree is True
               else pal.bad_text('NO - %s address(es) differ' % num_words(data.get('differs_n')
                                                                         or 0))
               if agree is False else pal.warn_text('one of them could not be read'))
        print_table(pal, ['firewall', 'kind', 'address', 'ours on it', 'theirs', 'behind by',
                          'last written', 'right now'],
                    [[w['words'], w.get('kind') or 'mikrotik', w['host'] or '-',
                      '-' if w.get('on_router') is None else num_words(w['on_router']),
                      '-' if w.get('theirs') is None else num_words(w['theirs']),
                      '-' if w.get('missing_n') is None
                      else ('none' if not w['missing_n'] else num_words(w['missing_n'])),
                      stamp(w['at']) if w.get('at') else 'never',
                      ('could not be read' if not w.get('reached')
                       else (w.get('trouble') or 'answering'))]
                     for w in walls],
                    right=(3, 4, 5), indent=2)
        if data.get('differs'):
            pal.note('  on one but not the other: %s%s'
                     % (', '.join(data['differs'][:8]),
                        ' and more' if (data.get('differs_n') or 0) > 8 else ''))
    if len(walls) == 1 and walls[0].get('kind') not in (None, 'mikrotik'):
        pal.kv('the firewall', '%s at %s' % (FW_KIND_WORDS.get(walls[0]['kind'], walls[0]['kind']),
                                              walls[0].get('host') or '-'))
    pal.title('Is the firewall carrying what it should be')
    for key, what in (('blocked', 'the banned list'), ('geo', 'the country list')):
        one = state.get(key) or {}
        if key == 'geo' and not one.get('on'):
            pal.kv(what, pal.soft('switched off'))
            continue
        step = one.get('in_sync')
        mark = (pal.ok_text('in sync') if step is True
                else pal.bad_text('OUT OF STEP') if step is False
                else pal.warn_text('cannot be told'))
        pal.kv(what, '%s · %s' % (mark, pal.soft(one.get('list') or '-')))
        if key == 'geo':
            got, want = one.get('on_router'), one.get('want')
            pal.note('    %s on the router, %s expected'
                     % ('could not be counted' if got is None else num_words(got),
                        'nothing has filled it yet' if want is None else num_words(want)))
        else:
            pal.note('    %s of ours on it · %s banned here · %s have not reached it · '
                     '%s of ours it should not be carrying'
                     % (num_words(one.get('on_router') or 0), num_words(one.get('want') or 0),
                        num_words(one.get('missing') or 0), num_words(one.get('extra') or 0)))
            if one.get('extra_few'):
                pal.note('    nothing here bans: %s' % ', '.join(one['extra_few']))
        if one.get('trouble'):
            pal.bad('    %s' % one['trouble'])
    if any((state.get(k) or {}).get('in_sync') is False for k in ('blocked', 'geo')):
        pal.note('\n  isemon --mikrotik --sync   puts both lists back as they should be')
    pal.title('The firewall is carrying %d entry(s) on %s (read in %d ms)'
              % (len(data['carrying']), data['list'], data['read_in_ms']))
    print_table(pal, ['address', 'ours', 'cc', 'why', 'comment'],
                [[r['address'], 'yes' if r['ours'] else 'no', r['country'] or '-',
                  (r['why'] or '')[:40], (r['comment'] or '')[:36]]
                 for r in data['carrying']], indent=2,
                paint=lambda n, i, cell: (
                    pal.c_addr if i == 0 else
                    ((pal.c_ok if cell == 'yes' else pal.dim) if i == 1 else
                     (pal.dim if i == 4 else None))))
    if data['not_carried']:
        pal.title('Kept out here but NOT on the firewall')
        print_table(pal, ['address', 'why'],
                    [[r['address'], (r['why'] or '')[:60]] for r in data['not_carried']],
                    indent=2)
    if data.get('trouble'):
        pal.bad('  the last look failed: %s' % data['trouble'])
    return 0


def cmd_fold(args, pal, store):
    """Fold the banned addresses into subnets, or say what folding would do.

    A scanner rents a /24 and works through it an address at a time. Forty
    rows on the router for forty addresses of one network is forty rules
    doing the work of one, and the fortieth is banned an hour after the
    first. Folding replaces them with the subnet.
    """
    session = cli_session(store)
    widest = None
    if str(args.fold).lower() not in ('plan', 'none', ''):
        try:
            widest = int(str(args.fold).lstrip('/'))
        except ValueError:
            pal.bad('  --fold takes a prefix length, like 24 or /24')
            return 1
        if not 8 <= widest <= 32:
            pal.bad('  a prefix length between 8 and 32, please')
            return 1
    status, data = api_call('/api/blocked/fold%s' % ('?widest=%d' % widest if widest else ''),
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    plan = data.get('plan') or {}
    groups = plan.get('groups') or []
    if as_json(args, data):
        return 0
    if not groups:
        pal.title('Nothing to fold')
        pal.note('  No subnet holds enough separately banned addresses to be worth one rule')
        pal.note('  instead of several. The bar is the fold_least setting.')
        return 0
    pal.title('%d subnet(s) would replace %d separately banned address(es)'
              % (len(groups), sum(len(g['members']) for g in groups)))
    print_table(pal, ['subnet', 'holds', 'already there', 'addresses'],
                [[(g['net'], pal.c_addr), (str(len(g['members'])), pal.c_num),
                  'yes' if g.get('existing') else 'no',
                  ', '.join(m['ip'] for m in g['members'][:4])
                  + (' and %d more' % (len(g['members']) - 4) if len(g['members']) > 4 else '')]
                 for g in groups], indent=2)
    if widest is None:
        pal.note('\n  This only said what it would do. To do it:')
        pal.note('    isemon --fold 24')
        return 0
    status, data = api_call('/api/blocked/fold', 'POST', {'apply': True, 'widest': widest},
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    return watch_job(pal, data['job'], session)


def cmd_fw_test(args, pal, store):
    """Try reaching it, as the button on the firewall's card does. (1.10.192)"""
    session = cli_session(store)
    fw = 'mikrotik2' if args.fw_test == '2' else 'mikrotik'
    status, data = api_call('/api/mikrotik', 'POST', {'test': True, 'fw': fw},
                            timeout=120.0, session=session)
    if status == 0:
        need_daemon(pal, status, data)
        return 1
    if as_json(args, data):
        return 0 if data.get('ok') else 1
    # The kind as the daemon has it: the settings saved on the dashboard are
    # its, and this process may not have read them. (1.10.192)
    _st, walls = api_call('/api/mikrotik', session=session)
    kind = (((walls or {}).get('walls') or {}).get(fw) or {}).get('kind') or 'mikrotik'
    pal.title('%s (%s)' % (fw_words(fw).capitalize(), FW_KIND_WORDS.get(kind, kind)))
    if data.get('ok'):
        pal.good('  it answered:')
        for line in str(data.get('said') or '').splitlines():
            pal.say('    %s' % line)
        return 0
    pal.bad('  it did not answer: %s' % (data.get('error') or 'status %s' % status))
    return 1


