def cmd_banfeed(args, pal, store):
    """The published ban list, from here. (1.10.192)"""
    session = cli_session(store)
    what = str(args.banfeed or 'state').strip().lower()
    if what in ('newkey', 'forget'):
        status, data = api_call('/api/banfeed-key' if what == 'newkey' else '/api/banfeed-forget',
                                'POST', {}, session=session)
        if not need_daemon(pal, status, data):
            return 1
        pal.good('  a new key: every firewall needs the new URL' if what == 'newkey'
               else '  who fetched it is forgotten')
        if what == 'forget':
            return 0
    elif what != 'state':
        if what not in BANFEED_FORMATS:
            pal.bad('  the formats are %s' % ', '.join(BANFEED_FORMATS))
            return 1
        status, data = api_call('/api/banfeed-preview?format=%s' % what, session=session)
        if not need_daemon(pal, status, data):
            return 1
        if as_json(args, data):
            return 0
        sys.stdout.write(data.get('body') or '')
        return 0
    status, data = api_call('/api/banfeed-state', session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    pal.title('The published ban list')
    pal.kv('switched', pal.ok_text('on') if data.get('on') else pal.soft('off'))
    pal.kv('format by default', data.get('format') or '-')
    pal.kv('in it now', num_words(data.get('count') or 0)
           if data.get('blacklist') else pal.soft('nothing - the blacklist is off'))
    pal.kv('proving who fetches', {'none': 'nothing', 'key': 'a key in the URL',
                                    'basic': 'user name and password (%s)'
                                    % (data.get('user') or '-')}.get(data.get('auth'),
                                                                     data.get('auth')))
    pal.kv('only from', 'the addresses in banfeed_from' if data.get('restricted')
           else 'anywhere the web server allows')
    key = data.get('key') or ''
    pal.title('Its URL, for each kind of firewall')
    pal.note('  on the dashboard\'s own web server, beside index.php:')
    for one in data.get('formats') or []:
        url = 'banfeed.php?f=%s%s' % (one['key'], ('&k=%s' % key) if key else
                                      ('&k=KEY' if data.get('auth') == 'key' else ''))
        pal.say('    %-10s %-26s %s' % (one['key'], url, pal.soft(one['words'])))
    fetched = data.get('fetched') or []
    pal.title('Fetched by')
    if not fetched:
        pal.note('  nobody yet')
    else:
        print_table(pal, ['from', 'format', 'last', 'times', 'entries'],
                    [[f.get('from'), f.get('format') or '-', stamp(f.get('at') or 0),
                      num_words(f.get('n') or 0), num_words(f.get('count') or 0)]
                     for f in fetched], right=(3, 4), indent=2)
    if data.get('refused'):
        pal.warn('  refused %s time(s)' % num_words(data['refused']))
    return 0


