def watch_job(pal, jid, session):
    """Follow a piece of work that takes long enough to be worth watching."""
    last = ''
    while True:
        status, data = api_call('/api/job?id=%s' % jid, session=session)
        if not need_daemon(pal, status, data):
            return 1
        job = data['job']
        if job['last'] != last:
            last = job['last']
            if job['total']:
                pal.say('  [%d/%d] %s' % (min(job['done_n'], job['total']),
                                          job['total'], last))
            else:
                pal.say('  %s' % last)
        if job['done']:
            if job['ok']:
                pal.good('  %s' % ((job.get('result') or {}).get('message') or 'done'))
                return 0
            pal.bad('  %s' % job['error'])
            return 1
        time.sleep(1.0)


def cmd_backup(args, pal, store):
    full = bool(getattr(args, 'full', False))
    where = store.backup(label='full' if full else 'cli')
    if full:
        # With the keys in it (1.10.222): as secret as the keys themselves.
        carried = full_carry(where)
        # Through the file itself, not its name (1.10.222).
        fd = os.open(str(where), os.O_RDONLY | os.O_NOFOLLOW)
        try:
            os.fchmod(fd, 0o600)
        finally:
            os.close(fd)
        store.add_event('backup', 'a full backup was made at the command line, with %s in it'
                        % ', '.join(carried), 'warn', who='the command line')
        store.prune_backups(int(CONFIG.get('backup_keep') or 14))
        pal.good('a full backup was made: %s (%s), with %s in it'
                 % (where, human_size(where.stat().st_size), ', '.join(carried)))
        pal.note('  It holds the key that opens every password and private key in it: keep it '
                 'as carefully as the key itself.')
        return 0
    store.prune_backups(int(CONFIG.get('backup_keep') or 14))
    pal.good('a copy was made: %s (%s)' % (where, human_size(where.stat().st_size)))
    rows = store.backups()
    if len(rows) > 1:
        pal.title('Copies kept')
        print_table(pal, ['name', 'size', 'made'],
                    [[b['name'], human_size(b['bytes']), stamp(b['at'])] for b in rows], indent=2)
    return 0


def cmd_dump(args, pal, store):
    """The nightly dump, made now, by hand.

    What the engine in use makes of itself: pg_dump, mariadb-dump, or on the
    file SQLite's own backup. It is what the daily copy makes every night,
    and this is the same thing on demand.
    """
    ready, why = store.dump_ready()
    if not ready:
        pal.bad(why)
        pal.note('  the nightly one falls back to a portable copy, which needs nothing '
                 'installed and goes back into any of the three engines.')
        return 1
    began = time.time()
    where = store.dump(label='cli')
    store.prune_dumps(int(CONFIG.get('backup_keep') or 14))
    pal.good('%s was made in %s: %s (%s)'
             % (ENGINE_DUMP_WORDS.get(store.dialect.name, 'a dump'),
                human_span(time.time() - began), where, human_size(where.stat().st_size)))
    pal.note('  it goes back into %s and nowhere else:  isemon --restore %s'
             % (ENGINE_WORDS.get(store.dialect.name, store.dialect.name), where.name))
    rows = store.dumps()
    if len(rows) > 1:
        pal.title('Dumps kept')
        print_table(pal, ['name', 'taken off', 'size', 'made'],
                    [[b['name'], ENGINE_WORDS.get(b['from'], b['from']),
                      human_size(b['bytes']), stamp(b['at'])] for b in rows], indent=2)
    return 0


def cmd_export(args, pal, store):
    """The configuration, out of the shell.

    `--export` on its own prints it, so it can be piped; `--export FILE`
    writes it, and writes it so that only its owner can read it, because a
    complete one holds a private key.
    """
    daemon = Daemon(store)
    data = daemon.export_config(secrets_too=bool(args.secrets))
    text = json.dumps(data, indent=1, ensure_ascii=False, default=str)
    if args.export == '-':
        print(text)
        return 0
    where = Path(str(args.export)).expanduser()
    where.parent.mkdir(parents=True, exist_ok=True)
    where.write_text(text + '\n', encoding='utf-8')
    try:
        os.chmod(where, 0o600 if args.secrets else 0o644)
    except OSError:
        pass
    if args.secrets:
        store.add_event('settings', 'the configuration was exported with the passwords and '
                        'keys in it', 'warn', who='the command line')
        pal.good('written to %s, with the passwords, the ssh key and the certificate in it'
                 % where)
        pal.warn('that file is enough to reach your router. It is readable only by its owner; '
                 'keep it where you keep passwords.')
    else:
        pal.good('written to %s' % where)
        pal.note('  no passwords, no ssh key and no certificate are in it. A machine built '
                 'from this one cannot reach the router or ask the domain anything until '
                 'those are set, and nobody can sign in until somebody sets a password.')
        pal.note('  --secrets puts all of them in.')
    return 0


def cmd_import(args, pal, store):
    """A configuration, back in."""
    where = Path(str(args.import_)).expanduser()
    try:
        given = json.loads(where.read_text(encoding='utf-8'))
    except OSError as e:
        pal.bad('%s could not be read: %s' % (where, e))
        return 1
    except ValueError as e:
        pal.bad('%s is not JSON: %s' % (where, e))
        return 1
    daemon = Daemon(store)
    said = daemon.import_config(given, by='the command line')
    pal.good('loaded from %s' % where.name)
    for one in said['done']:
        pal.note('  %s' % one)
    if said['missing']:
        pal.warn('that file could not bring these, and they have to be set by hand:')
        for one in said['missing']:
            pal.note('  %s' % one)
        if not said['complete']:
            pal.note('  a complete export - isemon --export FILE --secrets - carries all of '
                     'them, and so does a copy of the database.')
    if api_call('/api/health', timeout=3.0)[0] == 200:
        pal.note('the daemon is running and reads the settings again within a few seconds.')
    return 0


def cmd_restore(args, pal, store):
    """Put a copy of the database back, from the shell.

    The same check the dashboard does, the same copy of what is being
    replaced, and the same question asked out loud first - because a mistyped
    file name here costs a year of records, and --yes is there for the script
    that means it.
    """
    # A running daemon has this database open on several threads and its own
    # idea of where each log was read up to. Writing underneath it would be
    # overwritten by that idea within the minute - the restored positions
    # replaced by the ones it is holding - and the copy would look like it
    # had half worked. The dashboard does this properly because the daemon is
    # the one doing it; from here, it stops first.
    if api_call('/api/health', timeout=3.0)[0] == 200:
        pal.bad('the daemon is running and has this database open')
        pal.note('  stop it first, then put the copy back, then start it again:')
        pal.note('      systemctl stop isemon')
        pal.note('      isemon --restore %s' % args.restore)
        pal.note('      systemctl start isemon')
        pal.note('  or do it from the dashboard, under Settings -> the database, which does '
                 'all three without stopping anything.')
        return 1
    where = Path(str(args.restore)).expanduser()
    # A copy or a dump: it is read to find out which, rather than told by the
    # name it happens to have been saved under.
    said, why = store.dump_peek(where)
    if said is None:
        pal.bad(why)
        return 1
    counts = said.get('counts') or {}
    pal.title('What is in %s' % where.name)
    rows = []
    if said.get('kind') in ('', 'sqlite', None):
        rows = [['failed attempts', num_words(counts.get('failed', 0))],
                ['successful logins', num_words(counts.get('passed', 0))],
                ['banned right now', num_words(counts.get('blocked', 0))]]
    else:
        # A dump is not opened to be counted - that is what putting it back
        # is for. What can be read out of one without a server is what it is
        # and what is in it by table, and that is what is shown.
        rows = [['what it is', ENGINE_DUMP_WORDS.get(said['kind'], 'a dump')],
                ['tables in it', num_words(said.get('tables', 0))]]
    rows.append(['accounts', num_words(counts.get('users', 0))])
    rows.append(['size', human_size(said['bytes'])])
    print_table(pal, ['what', 'how many'], rows, indent=2)
    if not said.get('admins'):
        pal.bad('that %s has no full administrator in it - restoring it '
                'would lock everybody out of the dashboard'
                % ('database' if said.get('kind') in ('', 'sqlite', None) else 'dump'))
        return 1
    now = store.counts()
    pal.warn('this replaces everything in %s: %s failed attempt(s), %s login(s) '
             'and %s ban(s) recorded there now'
             % (store.path, num_words(now.get('failed', 0)),
                num_words(now.get('passed', 0)), num_words(now.get('blocked', 0))))
    if not args.yes:
        try:
            said_yes = input('  type the word restore to go ahead: ').strip().lower()
        except (EOFError, KeyboardInterrupt):
            said_yes = ''
        if said_yes != 'restore':
            pal.note('nothing was changed')
            return 1
    carried = carried_in(where)
    done = store.restore_dump(where)
    store.add_event('backup', 'the database was restored from %s at the command line; '
                    'a copy of what it replaced is %s' % (where.name, done['safety']),
                    'warn', who='the command line')
    carried_drop(store)
    put = carried_put(carried, 'the command line') if carried else []
    if put:
        pal.good('it was a full backup: %s put in place (the ones before are kept beside '
                 'them in %s)' % (', '.join(put), STATE_DIR))
    pal.good('restored from %s; what it replaced is in %s/%s'
             % (where.name, BACKUP_DIR, done['safety']))
    pal.note('  start the daemon again and it carries on from where this copy says it had '
             'read each log to, and writes the router:  systemctl start isemon')
    return 0


