# ---- Settings - System updates, from here (1.10.242) ------------------------------
# What the pane shows and asks, through the same /api/osup: what is waiting,
# a look for updates, an update with its bar and the package manager's lines,
# and Stop while it waits to begin. The daemon refuses here what it refuses
# there, in the same words.
OSUP_CLI_STATE = {'waiting': 'waits to begin', 'updating': 'updating',
                  'rebooting': 'restarting', 'done': 'done', 'failed': 'failed'}


def _osup_view_cli(session):
    status, v = api_call('/api/osup', timeout=30, session=session)
    return status, v


def _new_lines(old, new):
    """The lines of `new` not shown yet: what follows the part of `old` it
    still holds (the window slides, so the old lines go off its top)."""
    old, new = list(old or []), list(new or [])
    for k in range(min(len(old), len(new)), 0, -1):
        if old[-k:] == new[:k]:
            return new[k:]
    return new


def osup_restart_words(ck):
    """The page's 'A restart' fact."""
    if not ck.get('checked'):
        return ''
    if ck.get('reboot_now'):
        return 'needed now, before any update'
    if ck.get('reboot_after') and ck.get('count'):
        return 'needed after the update - %s' % ', '.join(ck.get('reboot_why') or [])
    return 'not needed by these updates'


def osup_print(pal, v, lines=True):
    """--os-updates: what is waiting, and the update under way or the last."""
    n = (v.get('nodes') or [{}])[0]
    ck = n.get('check') or {}
    plan = v.get('plan') or {}
    row = n.get('row') or {}
    pal.title('Updates of the system on %s' % (n.get('name') or socket.gethostname()))
    if not v.get('helper'):
        pal.bad(OSUP_NO_HELPER)
    pal.kv('updates waiting', ('looking...' if ck.get('state') == 'running' else
                               num_words(int(ck.get('count') or 0)) if ck.get('checked')
                               else 'not looked yet'))
    if ck.get('checked') and ck.get('security') is not None:
        pal.kv('of them security', num_words(int(ck['security'])))
    if ck.get('checked'):
        words = osup_restart_words(ck)
        pal.kv('a restart', pal.warn_text(words) if words.startswith('needed') else words)
        pal.kv('looked', '%s (%s)' % (human_age(time.time() - float(ck['checked'])),
                                      stamp(ck['checked'])))
    if ck.get('pm'):
        pal.kv('updated by', ck['pm'])
    if ck.get('error'):
        pal.bad('  %s' % ck['error'])
    pk = ck.get('packages') or []
    if pk and ck.get('state') != 'running':
        pal.head('What is waiting')
        for one in pk[:300]:
            pal.bullet(one)
        if len(pk) > 300:
            pal.note('    ...and %d more' % (len(pk) - 300))
    if plan.get('id'):
        st = row.get('state') or 'waiting'
        how = {'running': 'going on', 'done': 'done', 'failed': 'failed',
               'cancelled': 'stopped'}.get(plan.get('state') or 'running', plan.get('state'))
        pal.title('The update (%s)' % how)
        pal.kv('started by', '%s, %s' % (plan.get('by') or '?', stamp(plan.get('at'))))
        pal.kv('after it', 'restarted by itself when needed' if plan.get('reboot') == 'auto'
               else 'a restart it needs is asked for')
        if plan.get('state') == 'cancelled':
            pal.kv('step', 'stopped before it began - nothing was updated')
        else:
            pal.kv('step', OSUP_CLI_STATE.get(st, st) + (
                '  %s' % upgrade_bar(row.get('pct')) if st == 'updating' else ''))
            said = row.get('said') or ''
            if not said and plan.get('state') == 'running' and st == 'waiting':
                said = 'begins within seconds - it can be stopped until then ' \
                       '(isemon --os-update-stop)'
            if said:
                pal.kv('what happened', said)
        if lines:
            for line in (row.get('lines') or [])[-15:]:
                pal.note('    ' + line)
    if n.get('reboot') and not (v.get('power') or {}).get('id'):
        pal.warn('this server needs a restart: a new kernel or libraries are in that only a '
                 'restart brings into use - isemon --reboot')
    if v.get('refused'):
        pal.warn('an update may not begin now: %s' % v['refused'])
    if (v.get('power') or {}).get('id'):
        pal.note('  restarting - isemon --reboot shows nothing more; the server comes back by '
                 'itself')
    pal.blank()


def cmd_os_updates(args, pal, store):
    """--os-updates: what dnf (or apt) has waiting, and the update under way
    or the last one (Settings - System updates)."""
    session = cli_session(store)
    status, v = _osup_view_cli(session)
    if not need_daemon(pal, status, v):
        return 1
    if as_json(args, v):
        return 0
    osup_print(pal, v)
    return 0


def _osup_cli_follow_look(pal, session, quiet):
    """A look for updates followed until it is over: its lines as they come.
    The view at the end, or None when the daemon stopped answering."""
    shown = []
    while True:
        status, v = _osup_view_cli(session)
        if status != 200:
            need_daemon(pal, status, v)
            return None
        ck = ((v.get('nodes') or [{}])[0]).get('check') or {}
        lines = ck.get('lines') or []
        if not quiet:
            for line in _new_lines(shown, lines):
                pal.note('    ' + line)
        shown = lines
        if ck.get('state') != 'running':
            return v
        time.sleep(1.5)


def cmd_os_updates_check(args, pal, store):
    """--os-updates-check: Look for updates, followed until it is done."""
    session = cli_session(store)
    status, data = api_call('/api/osup', 'POST', {'action': 'check'}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    quiet = getattr(args, 'json', False)
    if not quiet:
        pal.note('  %s...' % (data.get('message') or 'looking for updates'))
    try:
        v = _osup_cli_follow_look(pal, session, quiet)
    except KeyboardInterrupt:
        pal.note('\n  no longer followed here; the look goes on (isemon --os-updates)')
        return 0
    if v is None:
        return 1
    if as_json(args, v):
        return 0
    osup_print(pal, v, lines=False)
    ck = ((v.get('nodes') or [{}])[0]).get('check') or {}
    return 1 if ck.get('state') == 'failed' else 0


def cmd_os_update(args, pal, store):
    """--os-update: every package of the system updated, as Update it now
    does - asked first unless --yes, then followed with its bar and what the
    package manager says until it is over. Ctrl+C stops the following, not
    the update."""
    session = cli_session(store)
    status, v = _osup_view_cli(session)
    if not need_daemon(pal, status, v):
        return 1
    how = args.reboot_after or 'ask'
    if not v.get('helper'):
        pal.bad(OSUP_NO_HELPER)
        return 1
    if v.get('refused'):
        pal.bad(v['refused'])
        return 1
    ck = ((v.get('nodes') or [{}])[0]).get('check') or {}
    quiet = getattr(args, 'json', False)
    if not args.yes:
        pal.title('Update this server')
        pal.say('  Every package of the system is updated.')
        pal.say('  When it needs one, the server is restarted by itself.' if how == 'auto' else
                '  A restart it needs is offered when it is done.')
        if ck.get('reboot_after') and ck.get('count'):
            pal.warn('This server needs a restart after this update: %s.'
                     % ', '.join(ck.get('reboot_why') or []))
        elif not ck.get('checked'):
            pal.note('  (not looked for updates yet: isemon --os-updates-check says what is '
                     'waiting)')
        try:
            said = input('  update this server now? type yes to go ahead: ').strip().lower()
        except (EOFError, KeyboardInterrupt):
            said = ''
        if said != 'yes':
            pal.note('  nothing was done')
            return 1
    status, data = api_call('/api/osup', 'POST', {'action': 'start', 'reboot': how},
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    plan_id = (data.get('plan') or {}).get('id')
    if not quiet:
        pal.good(data.get('message') or 'asked')
    shown, last, said_wait, restarting = [], None, False, False
    try:
        while True:
            status, v = _osup_view_cli(session)
            if status == 0 and restarting:
                if not quiet:
                    pal.good('updated - the server is restarting, as it needs; the update is '
                             'done when it is up again (isemon --os-updates)')
                return 0
            if not need_daemon(pal, status, v):
                return 1
            plan = v.get('plan') or {}
            n = (v.get('nodes') or [{}])[0]
            row = n.get('row') or {}
            if plan.get('id') != plan_id:
                if not quiet:
                    pal.note('  the update is not shown any more (hidden on the page) - '
                             'isemon --os-updates')
                return 0
            st = row.get('state') or 'waiting'
            if not quiet:
                for line in _new_lines(shown, row.get('lines') or []):
                    pal.note('    ' + line)
            shown = row.get('lines') or []
            if plan.get('state') == 'cancelled':
                if as_json(args, v):
                    return 1
                pal.warn('stopped before it began - nothing was updated')
                return 1
            if plan.get('state') == 'running':
                if st == 'waiting' and not said_wait and not quiet:
                    left = max(0, int(float(v.get('grace') or 10) -
                                      (time.time() - float(plan.get('at') or time.time()))))
                    pal.note('  it begins in %d s - until then isemon --os-update-stop stops '
                             'it' % left)
                    said_wait = True
                elif st == 'updating' and not quiet:
                    words = '%s  %s' % (upgrade_bar(max(8, min(95, int(row.get('pct') or 0)))),
                                        row.get('phase') or 'updating')
                    if words != last:
                        print('  ' + words)
                        last = words
                elif st == 'rebooting':
                    restarting = True
                    if last != 'rebooting' and not quiet:
                        pal.note('  %s' % (row.get('said') or 'updated - restarting, as it needs'))
                    last = 'rebooting'
                time.sleep(1.5)
                continue
            # Over: done or failed.
            if as_json(args, v):
                return 0 if plan.get('state') == 'done' else 1
            if plan.get('state') == 'done':
                print('  ' + upgrade_bar(100) + '  done')
                pal.good(row.get('said') or 'updated')
                if n.get('reboot') and not (v.get('power') or {}).get('id'):
                    pal.warn('it needs a restart to bring the new kernel or libraries into '
                             'use: isemon --reboot')
                return 0
            pal.bad('the update failed: %s' % (row.get('said') or 'it failed'))
            return 1
    except KeyboardInterrupt:
        pal.note('\n  no longer followed here; the update goes on (isemon --os-updates)')
        return 0


def cmd_os_update_stop(args, pal, store):
    """--os-update-stop: an update stopped while it waits to begin."""
    session = cli_session(store)
    status, data = api_call('/api/osup', 'POST', {'action': 'cancel'}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    pal.good(data.get('message') or 'stopped')
    return 0


# ---- Settings - SSH keys of root, from here (1.10.242) ----------------------------
# Through the same /api/sshkeys, so a full administrator's rights and root's
# helper decide here what they decide there. What is asked is done by root
# behind, within seconds: each command waits for it and says what root said.
def _sk_view(session):
    return api_call('/api/sshkeys', timeout=30, session=session)


def _sk_settle(pal, session, since=None, wait=90):
    """The keys once root has done what was asked (and, with `since`, read
    them after that moment). None when the daemon does not answer."""
    end = time.time() + wait
    v = {}
    while True:
        status, v = _sk_view(session)
        if not need_daemon(pal, status, v):
            return None
        done = not v.get('pending') and not v.get('busy')
        fresh = since is None or float(v.get('at') or 0) >= since or v.get('error')
        if (done and fresh) or not v.get('helper') or time.time() > end:
            return v
        time.sleep(0.5)


def sk_kind_words(k):
    t = str(k.get('type') or '?').upper()
    return t + (' %s' % k['bits'] if k.get('bits') and t != 'ED25519' else '')


def sk_print(pal, v):
    keys = v.get('keys') or []
    sd = v.get('sshd') or {}
    kept = v.get('kept') or {}
    pal.title('SSH keys of root on %s' % socket.gethostname())
    if not v.get('helper'):
        pal.warn('root\'s half of this is not installed on this machine yet (isemon-web.path): '
                 'run ./install.sh --upgrade from the 1.10.239 package (or later) once. Until '
                 'then the keys are neither read nor changed here')
    if v.get('error'):
        pal.bad('root said: %s' % v['error'])
    if sd.get('there') and sd.get('permit_root') == 'no':
        pal.warn('sshd does not let root sign in at all (PermitRootLogin no) - the keys below '
                 'are not used until it does')
    if sd.get('there') and sd.get('pubkey') == 'no':
        pal.warn('sshd takes no keys (PubkeyAuthentication no)')
    if not keys:
        pal.note('  ' + ('no key lets root in over SSH on this server' if v.get('at') else
                         'not read'))
    else:
        rows = []
        for k in keys:
            marks = []
            if kept.get('fp') and k.get('fp') == kept['fp']:
                marks.append('made here' if kept.get('how') == 'made' else 'given here')
            if k.get('options'):
                marks.append('with options')
            if k.get('readable') is False:
                marks.append('not read')
            rows.append([sk_kind_words(k), k.get('fp') or '-', k.get('comment') or '-',
                         ', '.join(marks)])
        print_table(pal, ['key', 'fingerprint', 'comment', ''], rows, indent=2)
    pal.blank()
    pal.kv('keys', str(len(keys)) if v.get('at') else '-')
    pal.kv('root may sign in', (sd.get('permit_root') or '?') if sd.get('there') else (
        'sshd is not here' if v.get('at') else '-'))
    if sd.get('there'):
        pal.kv('with a password', sd.get('password') or '?')
        if sd.get('port'):
            pal.kv('SSH port', str(sd['port']))
    pal.kv('the file', v.get('file') or '/root/.ssh/authorized_keys')
    pal.kv('read', human_age(time.time() - float(v['at'])) if v.get('at') else 'not yet')
    if v.get('pending'):
        pal.note('  being written...')
    pal.blank()


def cmd_root_keys(args, pal, store):
    """--root-keys: the keys that may sign in as root, read afresh, and what
    sshd makes of root (Settings - SSH keys of root)."""
    session = cli_session(store)
    status, v = _sk_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if v.get('helper'):
        asked = time.time() - 1
        status, data = api_call('/api/sshkeys', 'POST', {'action': 'refresh'}, session=session)
        if not need_daemon(pal, status, data):
            return 1
        v = _sk_settle(pal, session, since=asked, wait=30)
        if v is None:
            return 1
    if as_json(args, v):
        return 0
    sk_print(pal, v)
    return 1 if v.get('error') or not v.get('helper') else 0


def _sk_after(args, pal, session, words, blob=''):
    """What root said of the change just asked: said, and the keys now."""
    v = _sk_settle(pal, session)
    if v is None:
        return 1
    if as_json(args, v):
        return 1 if v.get('error') else 0
    if v.get('pending') or v.get('busy'):
        pal.warn('asked; root has not done it yet - isemon --root-keys in a minute')
        return 1
    if v.get('error'):
        pal.bad('root said: %s' % v['error'])
        return 1
    pal.good(words)
    for k in v.get('keys') or []:
        if blob and blob in str(k.get('text') or ''):
            pal.kv('fingerprint', k.get('fp') or '-')
    pal.kv('root\'s keys now', str(len(v.get('keys') or [])))
    return 0


def _key_text(given):
    """--root-key-add's LINE or FILE: what is in the file when it is one, a
    private key whole, else its first line."""
    p = Path(str(given)).expanduser()
    text = str(given)
    try:
        if p.is_file():
            if p.stat().st_size > 65536:
                raise ValueError('that file is far bigger than a key')
            text = p.read_text(errors='replace')
    except OSError as e:
        raise ValueError(str(e))
    text = text.strip()
    if 'PRIVATE KEY' in text:
        return text, True
    return (text.splitlines() or [''])[0].strip(), False


def _key_passphrase(args):
    """The passphrase of a private key: --passphrase-file, or
    ISEMON_KEY_PASSPHRASE in the environment - never the command line."""
    if getattr(args, 'passphrase_file', None):
        return Path(args.passphrase_file).expanduser().read_text().split('\n')[0].rstrip('\r')
    return os.environ.get('ISEMON_KEY_PASSPHRASE', '')


def cmd_root_key_add(args, pal, store):
    """--root-key-add LINE|FILE: a key put into root's authorized_keys - a
    public line or .pub file, or a private key of which only the public half
    goes in, as Add a key does."""
    try:
        text, private = _key_text(args.root_key_add)
        passphrase = _key_passphrase(args) if private else ''
    except (ValueError, OSError) as e:
        pal.bad(str(e))
        return 1
    session = cli_session(store)
    status, data = api_call('/api/sshkeys', 'POST', {'action': 'add', 'line': text,
                                                     'passphrase': passphrase},
                            session=session)
    if status == 400 and private and not passphrase and 'passphrase' in str(
            data.get('error') or '') and sys.stdin.isatty():
        try:
            passphrase = getpass.getpass('  the passphrase of the private key: ')
        except (EOFError, KeyboardInterrupt):
            passphrase = ''
        if passphrase:
            status, data = api_call('/api/sshkeys', 'POST', {'action': 'add', 'line': text,
                                                             'passphrase': passphrase},
                                    session=session)
    passphrase = ''
    if not need_daemon(pal, status, data):
        return 1
    if not getattr(args, 'json', False):
        pal.note('  %s' % (data.get('message') or 'asked'))
    blob = '' if private else (text.split() + ['', ''])[1]
    return _sk_after(args, pal, session, 'the key is in root\'s authorized_keys' + (
        ' - the private half was not kept' if private else ''), blob)


def cmd_root_key_drop(args, pal, store):
    """--root-key-drop FINGERPRINT: a key taken away, asked first unless
    --yes; the last one root signs in with only with --last, and asked
    again, as the page asks twice."""
    fp = str(args.root_key_drop or '').strip()
    session = cli_session(store)
    status, v = _sk_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if v.get('helper'):
        asked = time.time() - 1
        status, data = api_call('/api/sshkeys', 'POST', {'action': 'refresh'}, session=session)
        if not need_daemon(pal, status, data):
            return 1
        v = _sk_settle(pal, session, since=asked, wait=30)
        if v is None:
            return 1
    keys = [k for k in v.get('keys') or [] if k.get('fp')]
    k = ([x for x in keys if x['fp'] == fp] or [None])[0]
    if not v.get('helper'):
        pal.bad('root\'s half is not installed on this machine yet: run ./install.sh '
                '--upgrade (1.10.239 or later) once')
        return 1
    if k is None:
        pal.bad('no key of root has the fingerprint %s (isemon --root-keys lists them)' % fp)
        return 1
    last = len(keys) <= 1
    who = fp + (' (%s)' % k['comment'] if k.get('comment') else '')
    if last and not args.last:
        pal.bad('%s is the last key root signs in with on this server. Unless root may sign '
                'in with a password, nobody reaches it over SSH as root after this - '
                '--last takes it away all the same' % who)
        return 1
    if not args.yes:
        pal.say('  Root no longer signs in with %s on this server.' % who)
        if last:
            pal.warn('It is the last key root signs in with on this server. Unless root may '
                     'sign in with a password, nobody reaches it over SSH as root after this.')
        try:
            said = input('  take the key away? type yes to go ahead: ').strip().lower()
            if said == 'yes' and last:
                pal.say('  Said again: %s is the last key root signs in with on this server. '
                        'After it is gone, nobody reaches it over SSH as root with a key.' % fp)
                said = input('  take the last key away anyway? type yes to go ahead: ') \
                    .strip().lower()
        except (EOFError, KeyboardInterrupt):
            said = ''
        if said != 'yes':
            pal.note('  nothing was done')
            return 1
    status, data = api_call('/api/sshkeys', 'POST', {'action': 'drop', 'fp': fp,
                                                     'last_ok': bool(last and args.last)},
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    return _sk_after(args, pal, session, 'the key %s is taken away' % fp)


def cmd_root_key_make(args, pal, store):
    """--root-key-make ed25519|rsa4096: a key made as Make a key makes it.
    Its public half goes into root's authorized_keys; its private half is
    written once to --out (0600, never over a file there) or printed once,
    and kept nowhere else."""
    kind = args.root_key_make
    out = Path(args.out).expanduser() if args.out else None
    fd = None
    if out is not None:
        if os.path.lexists(str(out)):
            pal.bad('%s is there already: nothing was made (a file is never written over)'
                    % out)
            return 1
        try:
            # Made empty first, so that the key is not made for a file that
            # cannot be written - and never through a link put there meanwhile.
            fd = os.open(str(out), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            os.fchmod(fd, 0o600)
        except OSError as e:
            pal.bad('%s cannot be written: %s' % (out, e.strerror or e))
            return 1
    session = cli_session(store)
    status, data = api_call('/api/sshkeys', 'POST', {'action': 'rk_make', 'kind': kind},
                            session=session, timeout=180)
    if status != 200 or not data.get('private'):
        if fd is not None:
            os.close(fd)
            try:
                os.unlink(str(out))
            except OSError:
                pass
        if need_daemon(pal, status, data):
            pal.bad(data.get('error') or 'no key came back')
        return 1
    private = data.pop('private')
    if fd is not None:
        with os.fdopen(fd, 'w') as f:
            f.write(private if private.endswith('\n') else private + '\n')
            f.flush()
            os.fsync(f.fileno())
        data['out'] = str(out)
    private_shown = None if out is not None else private
    private = ''
    if getattr(args, 'json', False):
        v = _sk_settle(pal, session) or {}
        print(json.dumps(dict(data, private=private_shown, error=v.get('error') or '')
                         if private_shown else dict(data, error=v.get('error') or ''),
                         indent=2, ensure_ascii=False))
        return 1 if v.get('error') else 0
    pal.title('A new %s key for root' % ('Ed25519' if kind == 'ed25519' else 'RSA 4096'))
    if out is not None:
        pal.good('made - its private half is in %s (0600), and kept nowhere else' % out)
    else:
        pal.warn('made - keep the private half now, it is not shown again. Whoever holds it '
                 'signs in to this server as root:')
        sys.stdout.write(private_shown if private_shown.endswith('\n') else private_shown + '\n')
        sys.stdout.flush()
        private_shown = None
    pal.kv('fingerprint', data.get('fp') or '-')
    pal.kv('public half', data.get('pub') or '-')
    pal.note('  then, on your machine: ssh -i %s root@%s' % (
        out if out is not None else data.get('file') or 'the-key', socket.gethostname()))
    v = _sk_settle(pal, session)
    if v is None:
        return 1
    if v.get('error'):
        pal.bad('root said: %s - isemon --root-keys, and the public half again with '
                'isemon --root-key-add' % v['error'])
        return 1
    if (v.get('kept') or {}).get('on'):
        pal.good('its public half is in root\'s authorized_keys')
    else:
        pal.warn('its public half is not in root\'s authorized_keys yet - isemon --root-keys '
                 'in a minute')
    return 0


# ---- Settings - The OTP logs - Encrypted receiving, from here (1.10.245) ------------
# Through the same /api/otptls the card asks, so a full administrator's rights
# and root's helper decide here what they decide there. A change is done by
# root behind, within seconds (a minute when rsyslog-gnutls is installed
# first): each command waits for it and says what root said. The file otp
# made is opened by the daemon, in memory; its passphrase comes from a file
# (--passphrase-file), ISEMON_ZIP_PASSPHRASE or a question - never from the
# command line, and it is neither printed nor kept.
OTPTLS_NO_HELPER = ('root\'s half of this is not installed on this machine yet '
                    '(isemon-web.path): run ./install.sh --upgrade from the 1.10.245 package '
                    '(or later) once. Until then rsyslog\'s encrypted input is neither read nor '
                    'changed here')
OTPTLS_MODES = {'x509/name': 'mutual TLS - only the nodes named',
                'x509/certvalid': 'mutual TLS - any node with a certificate of otp\'s '
                                  'authority',
                'x509/fingerprint': 'mutual TLS - the nodes by fingerprint',
                'anon': 'TLS - otp checks isemon, any sender is taken'}
OTPTLS_HOW = {'otp': 'from the file otp made', 'made': 'made here, by this machine\'s '
              'authority', 'given': 'given by hand'}


def _ot_view(session):
    return api_call('/api/otptls', timeout=30, session=session)


def _ot_settle(pal, session, since=None, wait=300):
    """The view once root has done what was asked - and, with `since`, once
    the change asked at that moment is the last one. None when the daemon
    does not answer."""
    end = time.time() + wait
    v = {}
    while True:
        status, v = _ot_view(session)
        if not need_daemon(pal, status, v):
            return None
        done = not v.get('pending') and not v.get('busy')
        fresh = since is None or float((v.get('last') or {}).get('at') or 0) >= since
        if (done and fresh) or not v.get('helper') or time.time() > end:
            return v
        time.sleep(0.5)


def _ot_nodes(text):
    return [n for n in re.split(r'[\s,;]+', str(text or '').strip()) if n]


# ---- Settings - Automatic certificates, from here (1.10.251; otp 1.0.187) ----------
# What the pane shows and does, through the same /api/acme: the certificate,
# its name, who looks after it, its last order step by step; and Order it
# now, followed here - what is being waited for said as it goes.
def acme_print(pal, v):
    pal.title('Certificates by ACME: %s' % ('on' if v.get('on') else
                                            'off (isemon --set acme=1, and acme_*)'))
    pal.kv('the CA', v.get('directory') or '-')
    pal.kv('how it checks', v.get('challenge') or '-')
    pal.kv('the name', (v.get('name') or '(not known - isemon --set acme_name=NAME)') + (
        '' if v.get('named') else ' (by itself)' if v.get('name') else ''))
    left = (float(v['not_after']) - time.time()) / 86400 if v.get('not_after') else None
    pal.kv('the certificate', '%s, from %s, until %s%s' % (
        v.get('how') or 'as nginx has it', (v.get('issuer') or '?'), stamp(v.get('not_after')),
        ' (%d days left)' % left if left is not None else ''))
    pal.kv('looked after', 'ACME renews it' if v.get('care') else
           'its own certificate is kept (Look after it, or --acme-order, gives it to ACME)')
    if v.get('due') and v.get('on') and v.get('care'):
        pal.kv('due', v['due'])
    st = v.get('state') or {}
    if st.get('at'):
        pal.kv('last order', '%s %s by %s' % ('ok' if st.get('ok') else 'failed',
                                             stamp(st.get('at')), st.get('by') or '?'))
        if not st.get('ok') and st.get('said'):
            pal.bad('  ' + st['said'])
        for at, words in (st.get('steps') or [])[-12:]:
            pal.note('    +%3d s  %s' % (int(at - st['steps'][0][0]), words))
    else:
        pal.kv('last order', 'never ordered')
    if (v.get('work') or {}).get('busy'):
        pal.warn('being ordered now: %s' % (v['work'].get('says') or '...'))
    if v.get('manual'):
        pal.warn('waiting for a TXT record by hand: %s TXT "%s" - then on the page: It is in DNS'
                 % (v['manual'].get('rr'), v['manual'].get('txt')))
    b = v.get('before') or {}
    if b:
        pal.kv('before ACME', '%s, until %s%s - Back to the one before on the page' % (
            b.get('issuer') or b.get('how') or '?', stamp(b.get('not_after')),
            ' (ran out)' if b.get('ran_out') else ''))
    acc = v.get('account') or {}
    if acc.get('kid'):
        pal.kv('the account', '%s, made %s' % (acc.get('email') or '(no mail)', stamp(acc.get('at'))))
    pal.blank()


def cmd_acme(args, pal, store):
    """--acme: the certificate by ACME (Settings - Automatic certificates)."""
    status, v = api_call('/api/acme', timeout=30, session=cli_session(store))
    if not need_daemon(pal, status, v):
        return 1
    if as_json(args, v):
        return 0
    acme_print(pal, v)
    return 0


def cmd_acme_order(args, pal, store):
    """--acme-order this|all: Order it now, followed until it is over. One
    server: `this` and `all` are the same certificate."""
    if str(args.acme_order).strip().lower() not in ('this', 'all', 'dashboard'):
        pal.bad('which certificate: this (or all) - this server has one')
        return 1
    session = cli_session(store)
    status, v = api_call('/api/acme', 'POST', {'action': 'order'}, timeout=30, session=session)
    if not need_daemon(pal, status, v):
        return 1
    quiet = getattr(args, 'json', False)
    if not quiet:
        pal.good(v.get('message') or 'ordered')
    said, began = '', time.time()
    try:
        while True:
            status, v = api_call('/api/acme', timeout=30, session=session)
            if not need_daemon(pal, status, v):
                return 1
            w = v.get('work') or {}
            if not w.get('busy'):
                break
            if w.get('says') and w['says'] != said and not quiet:
                said = w['says']
                pal.note('  %s' % said)
            time.sleep(1)
    except KeyboardInterrupt:
        pal.note('\n  no longer followed here; the order goes on (isemon --acme)')
        return 0
    st = v.get('state') or {}
    if as_json(args, v):
        return 0 if st.get('ok') and float(st.get('at') or 0) >= began - 5 else 1
    if st.get('ok') and float(st.get('at') or 0) >= began - 5:
        for at, words in st.get('steps') or []:
            pal.note('    +%3d s  %s' % (int(at - st['steps'][0][0]), words))
        pal.good('the certificate for %s is made, good until %s; root puts it in within seconds'
                 % (st.get('name'), stamp(st.get('not_after'))))
        return 0
    pal.bad(st.get('said') or 'it did not go')
    return 1


def _ot_cert_lines(pal, key, f):
    """A certificate as a few lines: its names, who issued it, until when."""
    if not f:
        pal.kv(key, '-')
        return
    pal.kv(key, ', '.join(f.get('names') or []) or f.get('cn') or f.get('subject') or '?')
    if f.get('subject'):
        pal.kv('  subject', f['subject'])
    pal.kv('  issued by', f.get('issuer') or '?')
    pal.kv('  until', f.get('until') or '?')


def otptls_print(pal, v):
    kept = v.get('kept') or {}
    last = v.get('last') or {}
    pal.title('The otp logs over TLS on %s' % socket.gethostname())
    if not v.get('helper'):
        pal.warn(OTPTLS_NO_HELPER)
    if v.get('error'):
        pal.bad('root said: %s' % v['error'])
    if not v.get('read'):
        pal.note('  not read yet' + (' - isemon --otp-tls again in a few seconds'
                                     if v.get('helper') else ''))
    if v.get('on'):
        pal.kv('encrypted receiving', pal.ok_text('on') if v.get('mine') else pal.warn_text(
            'on - set up by hand, not here (set here, it is written over; the old file is '
            'kept beside it)'))
    else:
        pal.kv('encrypted receiving', 'off' if v.get('read') else '-')
    if v.get('on'):
        pal.kv('port', '%s/tcp' % (v.get('port') or '?'))
        pal.kv('mode', OTPTLS_MODES.get(v.get('auth') or '', v.get('auth') or '?'))
        pal.kv('nodes', ', '.join(v.get('peers') or []) or (
            '(any)' if v.get('auth') != 'x509/name' else '-'))
    if v.get('cert'):
        _ot_cert_lines(pal, 'certificate', v['cert'])
        if v.get('how'):
            pal.kv('  how', OTPTLS_HOW.get(v['how'], v['how']))
    elif v.get('read'):
        pal.kv('certificate', 'none yet')
    for i, c in enumerate(v.get('ca') or []):
        pal.kv('authority' if i == 0 else '', '%s (until %s)' % (
            c.get('subject') or '?', c.get('until') or '?'))
    own = v.get('own_ca') or {}
    if own.get('subject'):
        pal.kv('this machine\'s authority', '%s (until %s)' % (own['subject'],
                                                              own.get('until') or '?'))
    if v.get('on'):
        lis = v.get('listening')
        pal.kv('rsyslog listens', 'not known' if lis is None else pal.yes_no(
            lis, 'yes', pal.bad_text('no - rsyslog has not taken it (journalctl -u rsyslog)')))
        fo = v.get('fw_open')
        pal.kv('firewall', '%s%s' % (v.get('fw') or '?', '' if fo is None else (
            ' - the port is open' if fo else ' - ' + pal.warn_text('the port is not open'))))
    elif v.get('fw'):
        pal.kv('firewall', v['fw'])
    if v.get('version') or v.get('driver') or v.get('driver_there'):
        pal.kv('rsyslog', '%s%s' % (v.get('version') or '?', (
            ', TLS driver %s' % (v.get('driver') or v.get('driver_there')))
            if (v.get('driver') or v.get('driver_there')) else
            ', ' + pal.warn_text('no TLS driver yet (rsyslog-gnutls is installed when it is '
                                 'set up)')))
    plain = v.get('plain') or []
    if plain:
        pal.kv('plain 514, kept', ', '.join(sorted(set(
            '%s/%s%s' % (p.get('port'), p.get('proto') or '?',
                         ' (%s)' % p['file'] if p.get('file') else '') for p in plain))))
    elif v.get('read'):
        pal.kv('plain 514, kept', 'none read')
    if v.get('file'):
        pal.kv('the file', v['file'])
    if last.get('do'):
        pal.kv('the last change', '%s, by %s, %s - %s' % (
            OTPTLS_WORDS.get(last['do'], last['do']), last.get('by') or '?',
            human_age(time.time() - float(last.get('at') or 0)),
            pal.ok_text('done') if last.get('ok') else pal.bad_text('not done')))
        for line in v.get('said') or []:
            pal.bullet(line, indent='    ')
    elif kept.get('at'):
        pal.kv('the last change', '%s, by %s, %s' % (
            OTPTLS_WORDS.get(kept.get('do') or '', 'changed'), kept.get('by') or '?',
            stamp(kept['at'])))
    pal.kv('read', human_age(time.time() - float(v['at'])) if v.get('at') else 'not yet')
    if v.get('pending') or v.get('busy'):
        pal.note('  root is at it...')
    if v.get('trouble'):
        pal.blank()
        pal.warn('what went wrong with TLS since rsyslog started:')
        for line in v['trouble']:
            pal.note('    ' + line)
    pal.blank()


def cmd_otp_tls(args, pal, store):
    """--otp-tls: rsyslog's encrypted input for otp's logs, read afresh
    (Settings - The OTP logs - Encrypted receiving)."""
    session = cli_session(store)
    asked = time.time() - 1
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if v.get('helper'):
        # The view asks for a read itself when the last is old; else asked here.
        if not v.get('pending') and not v.get('busy'):
            status, data = api_call('/api/otptls', 'POST', {'action': 'refresh'},
                                    session=session)
            if not need_daemon(pal, status, data):
                return 1
        end = time.time() + 30
        while time.time() < end:
            status, v = _ot_view(session)
            if not need_daemon(pal, status, v):
                return 1
            if not v.get('busy') and (float(v.get('at') or 0) >= asked or v.get('error')):
                break
            time.sleep(0.4)
    if as_json(args, v):
        return 0
    otptls_print(pal, v)
    return 1 if v.get('error') or not v.get('helper') else 0


def _ot_after(args, pal, session, since, words):
    """What root said of the change just asked."""
    v = _ot_settle(pal, session, since=since)
    if v is None:
        return 1, {}
    last = v.get('last') or {}
    if as_json(args, v):
        return (0 if last.get('ok') and float(last.get('at') or 0) >= since else 1), v
    if v.get('pending') or v.get('busy'):
        pal.warn('asked; root has not done it yet - isemon --otp-tls in a minute')
        return 1, v
    if not v.get('helper'):
        pal.bad(OTPTLS_NO_HELPER)
        return 1, v
    if not last.get('ok') or float(last.get('at') or 0) < since:
        pal.bad('root said: %s' % (v.get('error') or 'nothing was changed'))
        return 1, v
    pal.good(words)
    for line in v.get('said') or []:
        pal.bullet(line)
    return 0, v


def _ot_wanted(args, v, conf=None):
    """port, mutual and nodes: what is given here, else what otp's file
    (or what is in place now) says."""
    conf = conf or {}
    port = args.otp_tls_port or conf.get('port') or (v.get('port') if v.get('on') else 0) \
        or 6514
    if args.otp_tls_mutual:
        mutual = args.otp_tls_mutual == 'yes'
    elif 'mutual' in conf:
        mutual = bool(conf['mutual'])
    else:
        mutual = bool(v.get('on')) and (v.get('auth') or 'anon') != 'anon'
    if args.otp_tls_nodes is not None:
        peers = _ot_nodes(args.otp_tls_nodes)
    elif 'peers' in conf:
        peers = list(conf.get('peers') or [])
    else:
        peers = list(v.get('peers') or [])
    return int(port), mutual, peers


def _ot_ca(args):
    """--otp-tls-ca FILE: otp's authority, PEM."""
    if not args.otp_tls_ca:
        return ''
    p = Path(args.otp_tls_ca).expanduser()
    if p.stat().st_size > 200000:
        raise ValueError('%s is far bigger than a certificate' % p)
    text = p.read_text(errors='replace')
    if 'BEGIN CERTIFICATE' not in text:
        raise ValueError('%s holds no certificate (PEM, -----BEGIN CERTIFICATE-----)' % p)
    return text


def _ot_mode_words(mutual, peers):
    if not mutual:
        return OTPTLS_MODES['anon']
    return OTPTLS_MODES['x509/name' if peers else 'x509/certvalid']


def _ot_yes(args, pal, question):
    if args.yes:
        return True
    try:
        said = input('  %s type yes to go ahead: ' % question).strip().lower()
    except (EOFError, KeyboardInterrupt):
        said = ''
    if said != 'yes':
        pal.note('  nothing was done')
        return False
    return True


def _zip_passphrase(args):
    """The passphrase of the file otp made: --passphrase-file, else
    ISEMON_ZIP_PASSPHRASE in the environment, else asked when there is a
    terminal - never the command line."""
    if getattr(args, 'passphrase_file', None):
        # Its name is not repeated: `--passphrase WORD` is taken by argparse
        # for --passphrase-file, and WORD would be printed back.
        try:
            text = Path(args.passphrase_file).expanduser().read_text(errors='replace')
        except OSError as e:
            raise ValueError('the file of --passphrase-file cannot be read (%s)'
                             % (e.strerror or e.__class__.__name__))
        return text.split('\n')[0].rstrip('\r')
    word = os.environ.get('ISEMON_ZIP_PASSPHRASE', '')
    if not word and sys.stdin.isatty():
        try:
            word = getpass.getpass('  the passphrase of the file (as typed in otp\'s wizard): ')
        except (EOFError, KeyboardInterrupt):
            word = ''
    return word


def cmd_otp_tls_import(args, pal, store):
    """--otp-tls-import ZIP: the file otp made (isemon-tls.zip) opened, shown,
    and put in with the port, the mode and the nodes otp's file says - unless
    given here. Asked first unless --yes."""
    quiet = getattr(args, 'json', False)
    if quiet and not args.yes:
        print(json.dumps({'ok': False, 'error': '--json does not ask: with --yes'}))
        return 1
    try:
        p = Path(args.otp_tls_import).expanduser()
        if p.stat().st_size > OTPTLS_ZIP_MOST:
            raise ValueError('%s is far bigger than the file otp makes' % p)
        data = p.read_bytes()
        passphrase = _zip_passphrase(args)
    except (ValueError, OSError) as e:
        pal.bad(str(e))
        return 1
    session = cli_session(store)
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    status, got = api_call('/api/otptls', 'POST', {
        'action': 'open', 'zip': base64.b64encode(data).decode('ascii'),
        'passphrase': passphrase}, session=session)
    passphrase = ''
    if not need_daemon(pal, status, got):
        return 1
    conf = got.get('conf') or {}
    port, mutual, peers = _ot_wanted(args, v, conf)
    if not quiet:
        pal.title('The file otp made: %s' % p.name)
        _ot_cert_lines(pal, 'certificate', got.get('cert') or {})
        ca = got.get('ca') or {}
        pal.kv('otp\'s authority', '%s (until %s)' % (ca.get('subject') or '?',
                                                      ca.get('until') or '?'))
        pal.kv('otp\'s file says', 'port %s, %s, nodes %s' % (
            conf.get('port') or '?', 'mutual TLS' if conf.get('mutual') else 'not mutual',
            ', '.join(conf.get('peers') or []) or '-'))
        pal.blank()
        pal.say('  Root puts the certificate and its key in (%s) and rsyslog receives '
                'otp\'s logs encrypted on %d/tcp, %s%s. The plain input on 514 stays as it '
                'is.' % (v.get('dir') or '/etc/pki/rsyslog/otp', port,
                         _ot_mode_words(mutual, peers),
                         (': ' + ', '.join(peers)) if mutual and peers else ''))
        if v.get('on'):
            pal.warn('It takes the place of the one in place now (port %s).' % v.get('port'))
        if not v.get('helper'):
            pal.bad(OTPTLS_NO_HELPER)
            return 1
        if not _ot_yes(args, pal, 'put it in?'):
            return 1
    asked = time.time() - 1
    status, data = api_call('/api/otptls', 'POST', {
        'action': 'apply', 'token': got.get('token') or '', 'port': port, 'mutual': mutual,
        'peers': peers}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    if not quiet:
        pal.note('  %s' % (data.get('message') or 'asked'))
    rc, _v = _ot_after(args, pal, session, asked, 'the otp logs are received over TLS on '
                       '%d/tcp' % port)
    return rc


def cmd_otp_tls_make(args, pal, store):
    """--otp-tls-make NAMES: a certificate for these names made here, by an
    authority of this machine's own, and put in; that authority's
    certificate printed (or written to --out), to paste into otp."""
    names = _ot_nodes(args.otp_tls_make)
    out = Path(args.out).expanduser() if args.out else None
    if not names:
        pal.bad('the names otp reaches this machine by: one at least')
        return 1
    if out is not None and os.path.lexists(str(out)):
        pal.bad('%s is there already: nothing was made (a file is never written over)' % out)
        return 1
    try:
        otp_ca = _ot_ca(args)
    except (ValueError, OSError) as e:
        pal.bad(str(e))
        return 1
    session = cli_session(store)
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    conf = {} if args.otp_tls_mutual else {'mutual': bool(otp_ca)}
    port, mutual, peers = _ot_wanted(args, v, conf)
    asked = time.time() - 1
    status, data = api_call('/api/otptls', 'POST', {
        'action': 'make', 'names': names, 'port': port, 'mutual': mutual, 'peers': peers,
        'otp_ca': otp_ca}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    if not getattr(args, 'json', False):
        pal.note('  %s' % (data.get('message') or 'asked'))
    rc, v = _ot_after(args, pal, session, asked, 'a certificate for %s made here and put in - '
                      'the otp logs are received over TLS on %d/tcp' % (', '.join(names), port))
    pem = (v.get('own_ca') or {}).get('pem') or ''
    if rc or not pem or getattr(args, 'json', False):
        return rc
    if out is not None:
        try:
            fd = os.open(str(out), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
            with os.fdopen(fd, 'w') as f:
                f.write(pem)
        except OSError as e:
            pal.bad('%s cannot be written: %s - isemon --otp-tls --json has it as own_ca.pem'
                    % (out, e.strerror or e))
            return 1
        pal.good('this machine\'s authority is in %s' % out)
    else:
        pal.blank()
        pal.say('  This machine\'s authority - what otp is to trust:')
        sys.stdout.write(pem if pem.endswith('\n') else pem + '\n')
        sys.stdout.flush()
    pal.note('  In otp: Settings → isemon → Encrypted sending → "isemon has one from its own '
             'CA", and paste %s there.' % ('the certificate in %s' % out if out is not None
                                           else 'the certificate above'))
    return 0


def cmd_otp_tls_set(args, pal, store):
    """--otp-tls-set: the port, the mode and the nodes changed, the
    certificate kept."""
    try:
        otp_ca = _ot_ca(args)
    except (ValueError, OSError) as e:
        pal.bad(str(e))
        return 1
    session = cli_session(store)
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if v.get('helper') and not v.get('cert') and v.get('read'):
        pal.bad('there is no certificate here yet: isemon --otp-tls-import (the file otp '
                'made) or isemon --otp-tls-make first')
        return 1
    port, mutual, peers = _ot_wanted(args, v)
    asked = time.time() - 1
    status, data = api_call('/api/otptls', 'POST', {
        'action': 'set', 'port': port, 'mutual': mutual, 'peers': peers, 'otp_ca': otp_ca},
        session=session)
    if not need_daemon(pal, status, data):
        return 1
    if not getattr(args, 'json', False):
        pal.note('  %s' % (data.get('message') or 'asked'))
    rc, _v = _ot_after(args, pal, session, asked, 'changed: %d/tcp, %s%s' % (
        port, _ot_mode_words(mutual, peers), (': ' + ', '.join(peers)) if mutual and peers
        else ''))
    return rc


def cmd_otp_tls_off(args, pal, store):
    """--otp-tls-off: the encrypted input taken away, asked first unless
    --yes. The plain one on 514 stays; so do the certificate and its key."""
    session = cli_session(store)
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if not v.get('helper'):
        pal.bad(OTPTLS_NO_HELPER)
        return 1
    if v.get('read') and not v.get('on'):
        if not as_json(args, v):
            pal.note('  the otp logs are not received over TLS here: nothing to switch off')
        return 0
    if not args.yes:
        if getattr(args, 'json', False):
            print(json.dumps({'ok': False, 'error': '--json does not ask: with --yes'}))
            return 1
        pal.say('  rsyslog no longer receives otp\'s logs encrypted on %s/tcp: a node that '
                'sends them there is not heard until it sends plain again. The plain input '
                'on 514 stays as it is; the certificate and its key are kept.'
                % (v.get('port') or '?'))
        if not _ot_yes(args, pal, 'switch it off?'):
            return 1
    asked = time.time() - 1
    status, data = api_call('/api/otptls', 'POST', {'action': 'off'}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    rc, _v = _ot_after(args, pal, session, asked, 'switched off - the plain input on 514 is '
                       'as it was')
    return rc


def cmd_otp_tls_remove(args, pal, store):
    """--otp-tls-remove (1.10.246): the encrypted receiving taken away whole -
    the input, isemon's certificate and key, otp's authority and the one made
    here. Asked first unless --yes. The plain input on 514 stays."""
    session = cli_session(store)
    status, v = _ot_view(session)
    if not need_daemon(pal, status, v):
        return 1
    if not v.get('helper'):
        pal.bad(OTPTLS_NO_HELPER)
        return 1
    if v.get('read') and not v.get('on') and not (v.get('cert') or {}).get('subject') and \
            not (v.get('own_ca') or {}).get('pem') and not v.get('ca'):
        if not as_json(args, v):
            pal.note('  nothing of the otp logs over TLS is here: nothing to remove')
        return 0
    if not args.yes:
        if getattr(args, 'json', False):
            print(json.dumps({'ok': False, 'error': '--json does not ask: with --yes'}))
            return 1
        pal.say('  rsyslog no longer receives otp\'s logs encrypted, and isemon\'s certificate, '
                'its key, otp\'s authority and the authority made here are deleted. The plain '
                'input on 514 stays as it is. A certificate made here again comes from a new '
                'authority, to paste into otp again.')
        if not _ot_yes(args, pal, 'remove it?'):
            return 1
    asked = time.time() - 1
    status, data = api_call('/api/otptls', 'POST', {'action': 'remove'}, session=session)
    if not need_daemon(pal, status, data):
        return 1
    rc, _v = _ot_after(args, pal, session, asked, 'removed - the plain input on 514 is as it '
                       'was')
    return rc


def cmd_web_status(args, pal, store):
    """What root has in place of what the pages asked: nginx, TLS, the
    firewall, and the last upgrade from the pages (1.10.222)."""
    held = type('Held', (), {'store': store})()
    wr, up = WebRoot(held), Upgrades(held)
    st = wr.read('status.json') or {}
    look = wr.read('look.json') or {}
    want = wr.request(look)
    upst = up.read_json('status.json') or {}
    out = {'web': {'helper': wr.helper_there(), 'asked': bool(want), 'status': st,
                   'current': bool(want and st.get('hash') == want.get('hash')),
                   'cert_days': wr.cert_days(), 'firewall': wr.fw_conf(),
                   'backend': look.get('backend'), 'look_at': look.get('at')},
           'upgrade': {'helper': up.unit_there(), 'status': upst, 'package': up.package()}}
    if as_json(args, out):
        return 0
    pal.title('What root has in place of what the pages asked')
    pal.kv('root\'s half', 'isemon-web.path' if wr.helper_there()
           else pal.warn_text('not installed - ./install.sh --upgrade once'))
    if not want:
        pal.kv('asked', 'nothing: nginx and the firewall are as they were')
    else:
        pal.kv('asked', ', '.join(k for k in ('access', 'tls', 'fw') if k in want))
        pal.kv('state', (st.get('state') or 'not put in yet') + (
            ' - in place' if out['web']['current'] else ' - NOT what is asked now'))
        if st.get('at'):
            pal.kv('last', stamp(st['at']))
        for line in st.get('said') or []:
            pal.note('    ' + line)
    fw = out['web']['firewall']
    pal.kv('the firewall', ('isemon\'s chain ISEMON-IN is on' if fw['on'] else 'left alone')
           + ('' if not look.get('backend') else ' (%s)' % look['backend']))
    if out['web']['cert_days'] is not None:
        pal.kv('certificate', '%d day(s) left' % out['web']['cert_days'])
    pal.title('Upgrades from the pages')
    pal.kv('root\'s half', 'isemon-upgrade.path' if up.unit_there()
           else pal.warn_text('not installed'))
    pk = out['upgrade']['package']
    pal.kv('waiting', ('isemon %s, signed by %s' % (pk['version'], pk.get('signed_by')))
           if pk else 'nothing')
    if upst:
        pal.kv('last', '%s to %s, %s' % (upst.get('state'), upst.get('version'),
                                        stamp(upst.get('at') or 0)))
        if upst.get('said'):
            pal.note('    ' + str(upst['said']))
    return 0


def upgrade_bar(pct, width=30):
    pct = max(0, min(100, int(pct or 0)))
    full = int(round(width * pct / 100.0))
    return '[%s%s] %3d %%' % ('#' * full, '-' * (width - full), pct)


def cmd_upgrade_check(args, pal, store):
    """What is at upgrade_url now, and whether it is newer (1.10.228)."""
    session = cli_session(store)
    status, data = api_call('/api/upgrade', 'POST', {'action': 'online_look'}, timeout=120,
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    o = (data.get('online') or {}).get('online') or {}
    # {url, packages, newest, newer, error} - what the console reads.
    if as_json(args, dict(o, url=o.get('url') or (data.get('online') or {}).get('url') or '')):
        return 0
    pal.title('New versions at %s' % (o.get('url') or (data.get('online') or {}).get('url') or
                                       '(no address set: upgrade_url)'))
    if o.get('error'):
        pal.bad('  it did not answer: %s' % o['error'])
        return 1
    older = 0
    for p in o.get('packages') or []:
        newer = Upgrades.ver_tuple(p['version']) > Upgrades.ver_tuple(__version__)
        if not newer and p['version'] != __version__:
            older += 1
            if older > 3:
                continue        # the rest under --downgrade-check
        pal.kv(p['version'], ('newer' if newer else ('this one' if p['version'] == __version__
                                                     else 'older')) +
               (' - %s' % human_size(p['bytes']) if p.get('bytes') else ''))
    if older > 3:
        pal.note('  ...and %d older (isemon --downgrade-check)' % (older - 3))
    if o.get('newer'):
        pal.good('isemon %s is there; this server runs %s - isemon --upgrade-online puts it in'
                 % (o['newest']['version'], __version__))
    else:
        pal.good('nothing newer than %s, which runs here' % __version__)
    return 0


def cmd_upgrade_follow(args, pal, store, began=None):
    """An upgrade going on, followed with its bar until it ends - started on
    the page or here. Ctrl+C stops the following, not the upgrade."""
    began = began or time.time()
    last_words = None
    seen_running = False
    session = cli_session(store)
    try:
        while True:
            status, data = api_call('/api/upgrade', timeout=20, session=session)
            if status == 0:
                # The daemon restarting under the upgrade: waited for.
                if seen_running:
                    if last_words != 'restarting':
                        print('  isemon is restarting...')
                        last_words = 'restarting'
                    time.sleep(2)
                    if time.time() - began > 1800:
                        pal.bad('isemon has not come back in half an hour - journalctl -u isemon')
                        return 1
                    continue
                pal.bad(data.get('error') or 'the daemon is not answering')
                return 1
            if status >= 400:
                pal.bad(data.get('error') or 'HTTP %s' % status)
                return 1
            run = data.get('run') or {}
            state = run.get('state') or ''
            if data.get('running') or state == 'running':
                seen_running = True
                pr = run.get('progress') or {}
                words = '%s  %s' % (upgrade_bar(pr.get('pct')), pr.get('words') or 'working')
                if words != last_words:
                    print('  ' + words)
                    last_words = words
                time.sleep(1.5)
                continue
            if not seen_running and not data.get('running'):
                if state in ('done', 'failed') and float(run.get('at') or 0) >= began - 5:
                    seen_running = True
                else:
                    pal.note('no upgrade is going on (the last: %s to %s, %s)'
                             % (state or 'none', run.get('version') or '-',
                                stamp(run.get('at') or 0) if run.get('at') else '-'))
                    return 0
            if state == 'done':
                pal.good('isemon %s is running' % data.get('version'))
                return 0
            if run.get('rc') is None and not run.get('said'):
                pal.bad('root did not take the upgrade up - is isemon-upgrade.path running?  '
                        'systemctl status isemon-upgrade.path')
            else:
                pal.bad('the upgrade failed: %s' % (run.get('said') or 'install.sh ended with %s'
                                                     % run.get('rc')))
            for line in (data.get('log') or [])[-15:]:
                pal.note('    ' + line)
            return 1
    except KeyboardInterrupt:
        pal.note('\n  no longer followed here; the upgrade goes on (isemon --upgrade-follow)')
        return 0


def cmd_upgrade_online(args, pal, store):
    """The newest version at upgrade_url - or the one named - fetched,
    checked by root's helper, and put in, followed here (1.10.228)."""
    session = cli_session(store)
    status, data = api_call('/api/upgrade', 'POST', {'action': 'online_look'}, timeout=120,
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    o = (data.get('online') or {}).get('online') or {}
    if o.get('error'):
        pal.bad('the address did not answer: %s' % o['error'])
        return 1
    want = str(args.upgrade_online or '').strip()
    if want in ('', 'newest', 'latest'):
        if not o.get('newer'):
            pal.good('nothing newer than %s, which runs here' % __version__)
            return 0
        want = o['newest']['version']
    if not [p for p in o.get('packages') or [] if p['version'] == want]:
        pal.bad('isemon %s is not at %s' % (want, o.get('url')))
        return 1
    if Upgrades.ver_tuple(want) <= Upgrades.ver_tuple(__version__):
        pal.bad('isemon %s is not newer than %s, which runs here' % (want, __version__))
        return 1
    pal.title('Upgrade to isemon %s' % want)
    pal.note('  fetched from %s, its signature checked by root, then install.sh --upgrade;'
             % o.get('url'))
    pal.note('  isemon restarts once, and for a minute nothing is read or banned.')
    if not args.yes:
        try:
            if input('  type yes to go on: ').strip().lower() != 'yes':
                pal.note('  nothing done')
                return 1
        except (EOFError, KeyboardInterrupt):
            pal.note('  nothing done')
            return 1
    began = time.time()
    status, data = api_call('/api/upgrade', 'POST', {'action': 'online_fetch', 'version': want,
                                                     'start': True}, timeout=600,
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    pal.good(data.get('message') or 'begun')
    return cmd_upgrade_follow(args, pal, store, began=began)


def cmd_downgrade_check(args, pal, store):
    """The older versions at upgrade_url, and which of them it is safe to go
    back to (1.10.232)."""
    session = cli_session(store)
    status, data = api_call('/api/upgrade', 'POST', {'action': 'online_look'}, timeout=120,
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    back = data.get('back') or {}
    if as_json(args, back):
        return 0
    pal.title('Going back from isemon %s' % __version__)
    if not back.get('offered'):
        pal.warn('  going back is switched off: Settings - Upgrades (Offer going back to an older '
                 'version), or isemon --set downgrade_offered=1')
    pal.kv('safe as far back as', back.get('floor') or '?')
    if back.get('error'):
        pal.bad('  the address did not answer: %s' % back['error'])
        return 1
    if not back.get('older'):
        pal.note('  no older version is at upgrade_url')
    for p in back.get('older') or []:
        pal.kv(p['version'], 'safe - the database is left as it is' if p.get('safe')
               else pal.warn_text('not safe: %s' % p.get('why')))
        if getattr(args, 'changes', False) and p.get('changelog'):
            for line in p['changelog'].splitlines():
                pal.note('      ' + line)
    for b in back.get('busy') or []:
        pal.warn('  not now: %s' % b)
    if any(p.get('safe') for p in back.get('older') or []):
        pal.note('  isemon --downgrade VERSION goes back to one of those marked safe.')
    return 0


def cmd_downgrade(args, pal, store):
    """Back to an older version from upgrade_url, as far back as is safe -
    root checks it again, and the database is left as it is (1.10.232)."""
    session = cli_session(store)
    want = str(args.downgrade or '').strip()
    status, data = api_call('/api/upgrade', 'POST', {'action': 'online_look'}, timeout=120,
                            session=session)
    if not need_daemon(pal, status, data):
        return 1
    back = data.get('back') or {}
    if not back.get('offered'):
        pal.bad('going back is switched off: Settings - Upgrades (Offer going back to an older '
                'version), or isemon --set downgrade_offered=1')
        return 1
    one = [p for p in back.get('older') or [] if p.get('version') == want]
    if not one:
        pal.bad('isemon %s is not at upgrade_url as an older version (isemon --downgrade-check '
                'lists them)' % want)
        return 1
    if not one[0].get('safe'):
        pal.bad('isemon %s: %s - going back that far is done by hand, with the database put '
                'back as well' % (want, one[0].get('why')))
        return 1
    if back.get('busy'):
        pal.bad('not now: %s' % '; '.join(back['busy']))
        return 1
    pal.title('Going back to isemon %s' % want)
    pal.note('  from %s; fetched, its signature checked by root, then its install.sh --upgrade.'
             % __version__)
    pal.note('  The database is left exactly as it is: %s and later can run on it.'
             % back.get('floor'))
    pal.note('  isemon restarts once, and for a minute nothing is read or banned.')
    if not args.yes:
        try:
            if input('  type the version to go back to: ').strip() != want:
                pal.note('  nothing done')
                return 1
        except (EOFError, KeyboardInterrupt):
            pal.note('  nothing done')
            return 1
    began = time.time()
    status, data = api_call('/api/upgrade', 'POST', {'action': 'go_back', 'version': want},
                            timeout=600, session=session)
    if not need_daemon(pal, status, data):
        return 1
    pal.good(data.get('message') or 'begun')
    return cmd_upgrade_follow(args, pal, store, began=began)


def cmd_upgrade_status(args, pal, store):
    """The last upgrade, what waits, and what the web has."""
    status, data = api_call('/api/upgrade', timeout=20, session=cli_session(store))
    if not need_daemon(pal, status, data):
        return 1
    if as_json(args, data):
        return 0
    pal.title('Upgrades')
    pal.kv('running now', 'isemon %s' % data.get('version'))
    pk = data.get('package')
    pal.kv('waiting', ('isemon %s, signed by %s' % (pk['version'], pk.get('signed_by')))
           if pk else 'nothing')
    run = data.get('run') or {}
    if run:
        pal.kv('last', '%s to %s, %s' % (run.get('state'), run.get('version'),
                                        stamp(run.get('at') or 0)))
    o = (data.get('online') or {}).get('online') or {}
    if o.get('at'):
        pal.kv('on the web', ('isemon %s is newer' % o['newest']['version']) if o.get('newer')
               else ('nothing newer (%s)' % o.get('error') if o.get('error') else 'nothing newer'))
        pal.kv('looked', stamp(o['at']))
    if data.get('running'):
        pal.note('  an upgrade is going on: isemon --upgrade-follow')
    return 0


def cmd_check(args, pal, store):
    """Is everything that should be running, running?"""
    bad = 0
    pal.title('isemon %s' % __version__)
    status, data = api_call('/api/health')
    if status == 200:
        pal.good('  the daemon is answering (up %s)' % human_span(data.get('uptime') or 0))
    else:
        pal.bad('  the daemon is NOT answering: %s' % (data.get('error') or status))
        bad += 1
    failed_name = str(CONFIG.get('ise_failed_name') or 'CISE_Failed_Attempts.log')
    # An installation that has said it has no ISE is not missing its logs.
    ise_on = (1 if CONFIG.get('ise') is None else int(CONFIG.get('ise') or 0))
    files = ([str(Path(folder) / failed_name) for folder in (CONFIG.get('ise_paths') or [])]
             if ise_on else [])
    if not ise_on:
        pal.good('  the ISE logs are switched off, so none of them is looked for')
    there = 0
    for path in files:
        if os.path.exists(path):
            there += 1
            age = time.time() - os.path.getmtime(path)
            pal.good('  %s is there (%s)' % (path, human_age(age)))
        else:
            # A node of an HA pair that has refused nobody yet has no
            # failed-attempt log at all, and that is ordinary rather than
            # wrong. What is wrong is when none of them is there.
            pal.warn('  %s is not there yet' % path)
    if files and not there:
        pal.bad('  no ISE log is there at all - nothing is being read, so nobody can be banned')
        bad += 1
    said = store.check()
    if said == 'ok':
        pal.good('  the database is sound (%s)' % human_size(store.size()))
    else:
        pal.bad('  the database says: %s' % said)
        bad += 1
    # A database that opened but did not finish being brought up to date is
    # the thing that goes wrong quietly: every query works until it meets the
    # one column that is not there.
    short = store.missing_columns()
    if short:
        pal.bad('  the database is missing %s - the upgrade did not finish'
                % ', '.join(short))
        pal.note('     restarting isemon adds them; if it does not, say so with the '
                 'output of isemon --check')
        bad += 1
    else:
        pal.good('  the database has everything this version needs')
    # Where the settings live, and whether that place can be written to. A
    # machine whose /etc is read-only is a machine where the old way of
    # keeping settings could not work at all, and this says so before
    # somebody meets it as a save that fails.
    if CONFIG_FILE.exists():
        pal.good('  %s is read for its settings%s'
                 % (CONFIG_FILE, '' if os.access(str(CONFIG_FILE), os.R_OK)
                    else ' - but it cannot be read'))
    else:
        pal.note('  %s does not exist, which is usual - settings are saved in the database'
                 % CONFIG_FILE)
    try:
        saved = len(store.settings_saved())
        pal.good('  %d setting(s) are saved in the database' % saved)
    except Exception as e:
        pal.bad('  the saved settings cannot be read: %s' % e)
        bad += 1
    if store.user_count():
        pal.good('  %d account(s) may open the dashboard' % store.user_count())
    else:
        pal.bad('  no account exists - nobody can open the dashboard')
        bad += 1
    # The certificate the dashboard answers with, and root's side of what
    # the pages ask (1.10.222) - as root last saw them.
    wr = WebRoot(type('Held', (), {'store': store})())
    days = wr.cert_days()
    if days is None:
        pass
    elif days < 0:
        pal.bad('  the dashboard\'s certificate ran out %d day(s) ago (Settings -> Certificates '
                'and TLS)' % -days)
        bad += 1
    elif days < 21:
        pal.warn('  the dashboard\'s certificate runs out in %d day(s) (Settings -> Certificates '
                 'and TLS)' % days)
    else:
        pal.good('  the dashboard\'s certificate is good for %d more day(s)' % days)
    st = wr.read('status.json') or {}
    if st.get('state') == 'failed':
        pal.warn('  root could not put in what Settings asked last: %s (isemon --web-status)'
                 % ((st.get('said') or ['?'])[-1])[:160])
    # A log dated in the future. The daemon is the only thing that knows,
    # because it is the only thing that has read the file; everything here
    # can do is ask it and repeat what it says. Worth asking: it is the one
    # trouble in this list that nothing else on the machine complains about.
    if status == 200:
        code, seen = api_call('/api/status', session=cli_session(store))
        if code != 200 or not isinstance(seen, dict) or 'logs' not in seen:
            # Not a failure of its own - this command is often run by
            # somebody who cannot sign in - but it must not read as an
            # all-clear about something it never managed to ask.
            pal.note('  whether any log is dated ahead of the clock could not be asked '
                     '(%s)' % (str((seen or {}).get('error') or code)[:60]))
        else:
            said = seen.get('log_zone_trouble') or ''
            if said:
                pal.bad('  %s' % said)
                bad += 1
            early = [t for t in seen.get('logs') or [] if t.get('ahead')]
            for t in early:
                pal.bad('  %s is dated %s ahead of this machine\u2019s clock'
                        % (t['path'], human_span(t['ahead'])))
                bad += 1
            if early:
                pal.note('     %s' % (early[0].get('ahead_says') or ''))
            elif not said:
                zone = str(seen.get('log_zone') or '')
                pal.good('  every log is dated at or before the moment it was read%s'
                         % (' (read as %s)' % zone if zone else ''))
    if not ssh_available():
        pal.note('  ssh is not installed, so no router can be reached')
    if CONFIG.get('debug'):
        # Not a fault, so it does not count against the all-clear; but a
        # machine left with this on writes megabytes a minute, and the way
        # that is noticed otherwise is a disk with nothing left on it.
        try:
            big = human_size(Path(_LOG_PATH).stat().st_size) if _LOG_PATH else ''
        except OSError:
            big = ''
        pal.note('  the debug switch is on%s - every statement and every request is '
                 'being written down' % (' and the log is %s' % big if big else ''))
        pal.note('    isemon --set debug=0      # when you are done')
    pal.say()
    if bad:
        pal.bad('%d thing(s) want attention' % bad)
    else:
        pal.good('everything is as it should be')
    return 1 if bad else 0


def preflight(pal):
    """The things that stop the daemon before it starts."""
    trouble = []
    if sys.version_info < (3, 8):
        trouble.append('Python 3.8 or newer is needed; this is %d.%d'
                       % sys.version_info[:2])
    for folder in (STATE_DIR, LOG_DIR.parent):
        try:
            Path(folder).mkdir(parents=True, exist_ok=True)
        except OSError as e:
            trouble.append('%s cannot be made: %s' % (folder, e))
    return trouble


# ---------------------------------------------------------------------------
# --help, written out rather than left to argparse
# ---------------------------------------------------------------------------
# argparse's help is correct and hard to read: every option in one column
# whatever it takes, no colour, and the one thing somebody wants - what do I
# type to do X - nowhere in it. This lays the same options out in two columns,
# wraps what it says against the width of the terminal, colours the parts that
# carry meaning, and ends with the handful of lines people actually type.
#
# It reads the parser rather than a list kept beside it, so an option added
# below appears here by itself and cannot fall out of sync.
HELP_EXAMPLES = [
    ('isemon --status', 'what it is doing right now'),
    ('isemon --check', 'is everything that should be running, running'),
    ('isemon --blocked', 'who is kept out, and for how long'),
    ('isemon --failed --hours 1', 'what has been refused in the last hour'),
    ('isemon --address 45.9.148.9', 'everything known about one address'),
    ('isemon --ban 45.9.148.9 --forever', 'keep one out by hand, for good'),
    ('isemon --unban 45.9.148.9', 'let it back in'),
    ('isemon --allow 10.0.0.0/8', 'never ban anything in this range'),
    ('isemon --rescan', 'go back over every log and apply what it earns'),
    ('isemon --rescan --logs tacplus', 'read one module’s logs again, from the beginning'),
    ('isemon --ptr-fill', 'look up the name behind every address that has none yet'),
    ('isemon --ptr 10.20.30.40', 'ask every name server what one address is called'),
    ('isemon --mikrotik', 'are both lists on the router in sync, and what is on them'),
    ('isemon --mikrotik --sync', 'put both lists on the router now'),
    ('isemon --passed --kind commands', 'what people ran on the switches over TACACS'),
    ('isemon --fold', 'what folding the bans into subnets would do'),
    ('isemon --set block_tries=8', 'change a setting (it goes in the database)'),
    ('isemon --passwd admin', 'set or reset somebody\'s password'),
    ('isemon --disable-user jan', 'stop an account signing in, keeping everything'),
    ('isemon --directory', 'is Active Directory reachable, and does it answer'),
    ('isemon --directory-groups ise', 'the groups it holds, to put in a role'),
]

# argparse writes its own words for the two it adds itself, and they are not
# in the voice of everything around them.
HELP_OWN_WORDS = {
    'help': 'this, and stop',
    'version': 'which version this is, and stop',
}

HELP_GROUP_SAYS = {
    'looking': 'Reading what it knows. None of these change anything.',
    'doing': 'Changing something: a ban, the router, the lists.',
    'settings': 'What it is set to. Saved in the database - except the few that say '
                'which database that is, which are in config.json.',
    'accounts': 'Who may open the dashboard. These talk to the database '
                'directly, so they work when nothing else does.',
}


def help_option_words(action):
    """An option as somebody types it, in two halves.

    The names and the value are two different things - one is typed exactly
    and the other is filled in - so they come back apart and are coloured
    apart. Written as one string, `--ban ADDR` reads as four words to type and
    that is how ADDR ends up in somebody's command line.
    """
    if not action.option_strings:
        return (action.metavar or action.dest or '', '')
    names = ', '.join(action.option_strings)
    if action.nargs == 0:
        return (names, '')
    metavar = action.metavar or (action.dest or '').upper()
    return (names, '[%s]' % metavar if action.nargs == '?' else metavar)


def help_text(parser, pal):
    """The whole of --help, in the width of this terminal."""
    width = pal.width
    out = []
    prog = parser.prog or 'isemon'

    out.append('%s %s' % (pal.paint(prog, pal.c_head), pal.hi(__version__)))
    out.append(pal.soft('a banning daemon for Cisco ISE: it reads both nodes\' syslog, works out '
                        'who is'))
    out.append(pal.soft('trying to break into the VPN, and carries that to a Mikrotik'))
    out.append('')
    out.append('%s %s %s' % (pal.paint('usage:', pal.c_key), prog,
                             pal.soft('[--json] [--no-color] [what to do]')))
    out.append(pal.soft('       with nothing at all, it runs the daemon in the foreground'))

    # Two columns: the options on the left, what they do on the right. The
    # left column is as wide as the widest option and no wider, so a set of
    # short options does not leave half the page empty.
    every = [a for group in parser._action_groups for a in group._group_actions]
    left = min(34, max([len(' '.join(x for x in help_option_words(a) if x))
                        for a in every] or [20]) + 2)
    gap = 2

    for group in parser._action_groups:
        actions = [a for a in group._group_actions if a.help != argparse.SUPPRESS]
        if not actions:
            continue
        name = group.title or ''
        if name in ('positional arguments', 'options', 'optional arguments'):
            name = 'everywhere'
        out.append('')
        out.append(pal.paint(name.upper(), pal.c_head))
        says = HELP_GROUP_SAYS.get(group.title or '')
        if says:
            for line in textwrap.wrap(says, width - 2):
                out.append('  ' + pal.soft(line))
        for action in actions:
            names, metavar = help_option_words(action)
            words = ' '.join(x for x in (names, metavar) if x)
            painted = (pal.paint(names, pal.c_ok)
                       + (' ' + pal.paint(metavar, pal.c_warn) if metavar else ''))
            says = HELP_OWN_WORDS.get(action.dest) or action.help or ''
            if action.choices and '%s' not in says:
                says += ' (one of: %s)' % ', '.join(str(c) for c in action.choices)
            if (action.default not in (None, False, argparse.SUPPRESS)
                    and action.nargs != 0 and action.default != []):
                says += ' [%s]' % action.default
            room = max(24, width - left - gap - 2)
            lines = textwrap.wrap(says, room) or ['']
            # plain_pad measures what the text looks like, so the width it is
            # given is the width it should look - the escape sequences inside
            # it are not part of that and must not be added to it.
            out.append('  %s%s%s' % (plain_pad(painted, left), ' ' * gap, lines[0]))
            for more in lines[1:]:
                out.append('  %s%s%s' % (' ' * left, ' ' * gap, more))

    out.append('')
    out.append(pal.paint('THINGS PEOPLE ACTUALLY TYPE', pal.c_head))
    wide = max(plain_len(c) for c, _ in HELP_EXAMPLES) + 2
    for command, says in HELP_EXAMPLES:
        out.append('  %s%s' % (plain_pad(pal.paint(command, pal.c_info), wide),
                               pal.soft(says)))

    out.append('')
    out.append(pal.soft('  the dashboard is at https://<this machine>/ · '
                        'settings are kept in %s' % DB_FILE))
    out.append(pal.soft('  colour is off when this is piped, and with --no-color or NO_COLOR=1'
                        + ('' if HAVE_COLORAMA else ' (colorama is not installed)')))
    out.append('')
    return '\n'.join(out)


# ---------------------------------------------------------------------------
# The console: isemon run by its menus, on the server's own screen (1.10.228)
# ---------------------------------------------------------------------------
# `isemon --console` - and, with `isemon --console-at-login on`, what root sees
# first after signing in at the console or over SSH. As otp's console, which
# it is a port of. Everything is done by the same `isemon ...` commands the
# command line has, each one run as it would be typed, so nothing here can do
# more than they do; plus the live log and the journal. q leaves it for the
# ordinary shell; ! opens a shell and comes back when it is closed. English,
# coloured with colorama when it is there.
#
# Options another version adds (the network, the time, remote backups,
# upgrades from the web) are offered by the menus here whether or not this
# version has them: the parser is asked first, and one it does not know is
# "not in this version" rather than a command that fails.
#
# The choice at login is kept in /etc itself, where only root writes - not
# in /etc/isemon, whose group the daemon's account is in and which could
# have put a link there for root to follow, or a pipe for root's login to
# hang on.
CONSOLE_FLAG = Path(os.environ.get('ISEMON_CONSOLE_FLAG', '/etc/isemon-console-login'))
CONSOLE_PROFILE = Path(os.environ.get('ISEMON_CONSOLE_PROFILE',
                                      '/etc/profile.d/zz-isemon-console.sh'))
# The programs the console runs itself, each one replaceable for the tests.
CONSOLE_SYSTEMCTL = os.environ.get('ISEMON_SYSTEMCTL', 'systemctl')
CONSOLE_JOURNALCTL = os.environ.get('ISEMON_JOURNALCTL', 'journalctl')


def isemon_argv(here=None):
    """How this program runs itself again (the console's commands): this
    same file, by this same Python, with nothing taken from the folder it
    is run in or from PYTHON* in the environment."""
    return [sys.executable, '-I', os.path.realpath(here or __file__)]


_CLI_PARSER_LOCK = threading.Lock()


class _ParserBuilt(Exception):
    """main() has built its parser: stop there."""


def cli_parser():
    """The command line's own parser, exactly as main() builds it - so that
    the console knows which options this version has. main() is run up to
    the point where it would read the arguments, and stopped there: nothing
    is opened, read or written."""
    got = {}

    def grab(self, args=None, namespace=None):
        got['parser'] = self
        raise _ParserBuilt()
    with _CLI_PARSER_LOCK:
        real = HelpfulParser.parse_args
        HelpfulParser.parse_args = grab
        try:
            main(['--version'])
        except _ParserBuilt:
            pass
        finally:
            HelpfulParser.parse_args = real
    return got.get('parser')


def cli_options():
    """{'--option': its choices or None} for every option this version has."""
    parser = cli_parser()
    if parser is None:
        return {}
    return {name: (tuple(str(c) for c in action.choices) if action.choices else None)
            for name, action in parser._option_string_actions.items()}


def cli_missing(args, known):
    """What in `args` (an isemon command line) this version does not have:
    an option it does not know, or a word one of its options does not take.
    None when it has all of it."""
    args = [str(a) for a in args]
    for i, a in enumerate(args):
        if not a.startswith('--'):
            continue
        name = a.split('=', 1)[0]
        if name not in known:
            return name
        choices = known.get(name)
        if choices and i + 1 < len(args) and not args[i + 1].startswith('--') \
                and args[i + 1] not in choices:
            return '%s %s' % (name, args[i + 1])
    return None


class ConsoleBack(Exception):
    """Back to the menu."""


class Console(object):
    # The words of the log's levels, by how bad.
    LOG_TONES = {'error': 'bad', 'crit': 'bad', 'warn': 'warn', 'info': '', 'debug': 'dim'}
    LIVE_KEEP = 20000
    HELP = ' Up/Down move   Enter choose   Esc back   ! shell   q leave '
    ROLES = [('fulladmin', 'fulladmin - everything'),
             ('banadmin', 'banadmin - looks, bans and lets back in'),
             ('readonly', 'readonly - looks, changes nothing')]

    def __init__(self, pal, config=None):
        self.pal = pal
        self.config = config
        self.me = os.path.realpath(__file__)
        self._known = None
        self.st, self.st_gen, self.st_now, self.closing, self.plain = {}, 0, False, False, False
        self.backdrop = None

    # ---- small things ---------------------------------------------------------------
    def base(self):
        return isemon_argv(self.me) + (['--config', str(self.config)] if self.config else [])

    def known(self):
        """The options this version has, asked of its parser once."""
        if self._known is None:
            try:
                self._known = cli_options()
            except Exception:                           # noqa: BLE001
                self._known = {}
        return self._known

    def missing(self, args):
        return cli_missing(args, self.known())

    def out(self, *args):
        """`isemon ARGS --json`, read; None when it gave no JSON."""
        if self.missing(args):
            return None
        try:
            got = subprocess.run(self.base() + [str(a) for a in args] + ['--json'],
                                 capture_output=True, text=True, timeout=60,
                                 stdin=subprocess.DEVNULL)
            return json.loads(got.stdout or 'null')
        except Exception:                               # noqa: BLE001
            return None

    @staticmethod
    def _quote(a):
        a = str(a)
        return a if re.match(r'^[A-Za-z0-9_@%+=:,./-]+\Z', a) else "'%s'" % a.replace("'", "'\\''")

    def shown(self, args):
        return '$ isemon ' + ' '.join(self._quote(a) for a in args)

    def dim(self, t):
        return self.pal.paint(t, self.pal.dim)

    @staticmethod
    def utf():
        return 'utf' in (getattr(sys.stdout, 'encoding', '') or '').lower()

    # ---- keys on the ordinary terminal: Esc goes back everywhere --------------------
    def _raw(self):
        """The terminal's settings, to be put back; None without a terminal."""
        try:
            import termios
            return termios.tcgetattr(sys.stdin.fileno())
        except Exception:                               # noqa: BLE001
            return None

    def _restore(self, was):
        if was is None:
            return
        import termios
        termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, was)

    def key(self, wait=None):
        """One key, without Enter: 'esc', 'enter', 'bs', 'up'..., a character -
        or None when `wait` seconds went by without one."""
        import tty
        fd = sys.stdin.fileno()
        was = self._raw()
        try:
            if was is not None:
                # TCSANOW: what was typed ahead is kept, not thrown away.
                import termios
                tty.setcbreak(fd, termios.TCSANOW)
            r, _w, _x = select.select([fd], [], [], wait)
            if not r:
                return None
            ch = os.read(fd, 1)
            if ch == b'\x1b':
                # Alone, Esc; followed at once by more, a key's sequence.
                r, _w, _x = select.select([fd], [], [], 0.05)
                if not r:
                    return 'esc'
                rest = os.read(fd, 8)
                full = {b'[5~': 'pgup', b'[6~': 'pgdn', b'[1~': 'home', b'[4~': 'end',
                        b'[7~': 'home', b'[8~': 'end', b'[H': 'home', b'[F': 'end',
                        b'OH': 'home', b'OF': 'end'}.get(rest)
                if full:
                    return full
                return {b'[A': 'up', b'[B': 'down', b'[C': 'right', b'[D': 'left', b'OA': 'up',
                        b'OB': 'down', b'OC': 'right', b'OD': 'left'}.get(rest[:2], 'seq')
            if ch in (b'\r', b'\n'):
                return 'enter'
            if ch in (b'\x7f', b'\x08'):
                return 'bs'
            if ch == b'\x03':
                return 'ctrl-c'
            if ch == b'\x04':
                return 'ctrl-d'
            if ch == b'\x15':
                return 'ctrl-u'
            try:
                return ch.decode('utf-8')
            except UnicodeDecodeError:
                more = ch
                while len(more) < 4:
                    more += os.read(fd, 1)
                    try:
                        return more.decode('utf-8')
                    except UnicodeDecodeError:
                        continue
                return ''
        finally:
            self._restore(was)

    def pause(self):
        sys.stdout.write(self.dim('\n  Enter or Esc - back to the menu '))
        sys.stdout.flush()
        if self._raw() is None:
            try:
                input()
            except EOFError:
                pass
            return
        while self.key() not in ('enter', 'esc', 'ctrl-c', 'ctrl-d', 'q'):
            pass
        sys.stdout.write('\n')

    def clear_screen(self):
        if sys.stdout.isatty():
            sys.stdout.write('\033[H\033[2J')
            sys.stdout.flush()

    # ---- the bar at the top ---------------------------------------------------------
    # As `isemon --status --json` says it: how many are banned, whether the
    # logs are being read, the one verdict the dashboard's header draws, and
    # a change waiting to be kept where this version has one. Asked again
    # every 30 s off the screen's thread - the menu never waits for it - and
    # not at all while nobody sees the bar (a live view, a page, a shell).
    def status_thread(self):
        def look():
            while not self.closing:
                if self.plain and not self.st_now:
                    time.sleep(0.5)
                    continue
                self.st_now = False
                st = self.out('--status')
                active = '?'
                if shutil.which(CONSOLE_SYSTEMCTL):
                    try:
                        active = subprocess.run([CONSOLE_SYSTEMCTL, 'is-active', 'isemon'],
                                                capture_output=True, text=True,
                                                timeout=10).stdout.strip() or '?'
                    except Exception:                   # noqa: BLE001
                        pass
                self.st = dict(st if isinstance(st, dict) else {}, _active=active,
                               _answered=isinstance(st, dict))
                self.st_gen += 1
                for _ in range(60):
                    if self.closing or self.st_now:
                        break
                    time.sleep(0.5)
        threading.Thread(target=look, name='isemon-console-status', daemon=True).start()

    @staticmethod
    def bar_bits(st, now=None):
        """The facts on the right of the bar, most wanted first."""
        now = time.time() if now is None else now
        bits = []
        if not st or not st.get('_answered', True):
            return bits
        blocked = st.get('blocked') or {}
        if isinstance(blocked, dict) and blocked.get('now') is not None:
            bits.append('%s banned' % num_words(int(blocked.get('now') or 0)))
        tails = st.get('logs')
        if isinstance(tails, list):
            if not tails:
                bits.append('no log set up')
            else:
                read_at = max([float(t.get('looked') or 0) for t in tails
                               if isinstance(t, dict)] or [0])
                if not read_at:
                    bits.append('logs not read yet')
                elif now - read_at <= 120:
                    bits.append('logs read')
                else:
                    bits.append('logs NOT read for %s' % human_span(now - read_at))
        if st.get('users') is not None:
            bits.append('%s account(s)' % st.get('users'))
        return bits

    @staticmethod
    def status_lines(st, now=None):
        """The lines under the bar: [(words, tone)] - what is wrong, a switch
        that is off, a change waiting to be kept."""
        now = time.time() if now is None else now
        out = []
        if not st:
            return out
        if st.get('_answered') is False:
            out.append(('the daemon is not answering (isemon --status)', 'bad'))
            return out
        if st.get('blacklist_on') is False:
            out.append(('BANNING IS OFF - nobody is being kept out', 'warn'))
        db = st.get('database') or {}
        if isinstance(db, dict) and db.get('trouble'):
            out.append(('the database will not open: %s' % str(db['trouble'])[:120], 'bad'))
        health = st.get('health') or {}
        if isinstance(health, dict) and health.get('level') not in (None, 'ok') \
                and health.get('says'):
            out.append(('! ' + str(health['says']), 'bad' if health['level'] == 'crit'
                        else 'warn'))
        for one in st.get('problems') or []:
            out.append(('! ' + str(one), 'warn'))
        for key in st.get('settings_unread') or []:
            out.append(('a setting could not be read: %s' % key, 'warn'))
        jobs = [j for j in st.get('jobs') or [] if isinstance(j, dict)]
        if jobs:
            out.append(('%d long job(s) going on: %s (Status > Long jobs)' % (
                len(jobs), ', '.join(str(j.get('kind') or j.get('id')) for j in jobs[:3])), ''))
        # A change on trial (the network, the firewall): kept, or it goes
        # back by itself. Read as the version that has it says it.
        trials = st.get('trials') or []
        if isinstance(trials, dict):
            trials = [dict(v, kind=k) for k, v in trials.items() if isinstance(v, dict)]
        for t in trials:
            if not isinstance(t, dict):
                continue
            left = max(0, int(float(t.get('until') or 0) - now))
            out.append(('%s waits to be kept: %d:%02d left (Network, time and power > Keep or '
                        'put back)' % ('the new network' if t.get('kind') == 'net'
                                       else 'the change of the firewall', left // 60, left % 60),
                        'warn'))
        return out

    # ---- the menus: a text screen, arrows and Enter -------------------------------
    def _safe(self, text):
        """Words a terminal that is not UTF-8 can take: what it cannot, a ?."""
        text = str(text)
        return text if self.utf() else text.encode('ascii', 'replace').decode('ascii')

    def _put(self, y, x, text, attr=0):
        try:
            h, w = self.scr.getmaxyx()
            if y < 0 or y >= h or x >= w:
                return
            self.scr.addnstr(y, x, self._safe(text), max(0, w - x - (1 if y == h - 1 else 0)),
                             attr)
        except Exception:                               # noqa: BLE001 - the edge
            pass

    def _colours(self):
        c = self.curses
        self.A = {'head': c.A_REVERSE, 'sel': c.A_REVERSE | c.A_BOLD, 'ok': c.A_BOLD,
                  'warn': c.A_BOLD, 'bad': c.A_BOLD, 'dim': c.A_DIM, 'key': c.A_BOLD,
                  'title': c.A_BOLD}
        if not self.pal.on or not c.has_colors():
            return
        try:
            c.start_color()
            try:
                c.use_default_colors()
                bg = -1
            except Exception:                           # noqa: BLE001
                bg = c.COLOR_BLACK
            c.init_pair(1, c.COLOR_BLACK, c.COLOR_CYAN)
            c.init_pair(2, c.COLOR_BLACK, c.COLOR_GREEN)
            c.init_pair(3, c.COLOR_GREEN, bg)
            c.init_pair(4, c.COLOR_YELLOW, bg)
            c.init_pair(5, c.COLOR_RED, bg)
            c.init_pair(6, c.COLOR_CYAN, bg)
            self.A.update(head=c.color_pair(1), sel=c.color_pair(2) | c.A_BOLD,
                          ok=c.color_pair(3) | c.A_BOLD, warn=c.color_pair(4) | c.A_BOLD,
                          bad=c.color_pair(5) | c.A_BOLD, key=c.color_pair(6) | c.A_BOLD)
        except Exception:                               # noqa: BLE001
            pass

    def draw(self, title, items, sel, top, path):
        scr, A = self.scr, self.A
        scr.erase()
        h, w = scr.getmaxyx()
        st = self.st or {}
        self._put(0, 0, ' ' * w, A['head'])
        left = ' isemon %s  %s ' % (__version__, socket.gethostname())
        self._put(0, 0, left, A['head'] | self.curses.A_BOLD)
        active = st.get('_active') or '...'
        svc = ' service %s ' % active
        self._put(0, len(left) + 1, svc, A['sel'] if active == 'active' else
                  (A['head'] if active == '...' else self.curses.A_REVERSE | A['bad']))
        bits = self.bar_bits(st)
        # Too long for the bar: the last facts give way; still too long, it
        # goes on the line under the bar.
        y = 1
        for n in range(len(bits), -1, -1):
            right = (' ' + ' | '.join(bits[:n]) + ' ') if n else ''
            if len(left) + len(svc) + len(right) + 2 < w:
                if right:
                    self._put(0, w - len(right), right, A['head'])
                break
        if bits and len(left) + len(svc) + len(' ' + bits[0] + ' ') + 2 >= w:
            self._put(1, 1, ' | '.join(bits), A['key'])
            y = 2
        for words, tone in self.status_lines(st)[:max(0, min(5, h - 12))]:
            self._put(y, 1, words, A.get(tone, 0) if tone else 0)
            y += 1
        y += 1
        self._put(y, 2, path, A['dim'])
        self._put(y, 2 + len(path), title, A['title'])
        y += 2
        room = max(1, h - y - 2)
        if sel < top:
            top = sel
        if sel >= top + room:
            top = sel - room + 1
        width = max(20, min(w - 6, max(len(it[1]) for it in items) + 10))
        for n, it in enumerate(items[top:top + room]):
            i = top + n
            line = ' %3s  %s' % (it[0], it[1])
            line = line + ' ' * max(0, width - len(line))
            if i == sel:
                self._put(y + n, 2, line, A['sel'])
            else:
                self._put(y + n, 2, ' %3s' % it[0], A['key'])
                self._put(y + n, 8, it[1])
        if top > 0:
            self._put(y - 1, 4, '^ more', A['dim'])
        if top + room < len(items):
            self._put(y + room, 4, 'v more', A['dim'])
        self._put(h - 1, 0, ' ' * (w - 1), A['head'])
        self._put(h - 1, 0, self.HELP[:w - 1], A['head'])
        scr.noutrefresh()
        return top

    def menu(self, title, items, path=''):
        """items: [(key, words, function[, 'plain'])]; returns 'back' or 'quit'."""
        c = self.curses
        sel, top, typed, typed_at, seen = 0, 0, '', 0.0, -1
        while True:
            if self.plain:
                # Back from a command's screen: drawn whole, once.
                c.reset_prog_mode()
                self.scr.clear()
                self.plain = False
                self.st_now = True
            top = self.draw(title, items, sel, top, path)
            c.doupdate()
            self.backdrop = (lambda _s=sel, _t=top: self.draw(title, items, _s, _t, path))
            seen = self.st_gen
            k = None
            while True:
                k = self._getkey()
                if k is not None or self.st_gen != seen:
                    break
            if k is None:
                continue
            if k == 'resize':
                self.scr.clear()
                continue
            if k in ('up', 'k'):
                sel = (sel - 1) % len(items)
            elif k in ('down', 'j', 'tab'):
                sel = (sel + 1) % len(items)
            elif k in ('home', 'pgup'):
                sel = 0
            elif k in ('end', 'pgdn'):
                sel = len(items) - 1
            elif k in ('esc', 'left', 'bs'):
                if path:
                    return 'back'
            elif k in ('q', 'Q'):
                return 'quit'
            elif k == '!':
                self.go_plain(self.shell)
            elif len(k) == 1 and k.isdigit():
                now = time.time()
                typed = (typed if now - typed_at < 1.0 else '') + k
                typed_at = now
                hit = [i for i, it in enumerate(items) if it[0] == typed]
                if hit:
                    sel = hit[0]
                    # One that no longer number can grow into: chosen at once.
                    if not any(it[0].startswith(typed) and it[0] != typed for it in items):
                        k = 'enter'
                        typed = ''
            if k in ('enter', 'right'):
                it = items[sel]
                # Run on the text screen - its questions are windows there;
                # only a view of its own ('plain') leaves it.
                if len(it) > 3 and it[3] == 'plain':
                    r = self.go_plain(it[2])
                else:
                    try:
                        r = it[2]()
                    except ConsoleBack:
                        r = None
                if r == 'quit':
                    return 'quit'

    def go_plain(self, fn):
        """`fn` on the ordinary terminal - a command's output, the live log -
        and back to the screen after it."""
        c = self.curses
        c.def_prog_mode()
        c.endwin()
        self.plain = True
        if sys.stdout.isatty():
            sys.stdout.write('\033[H\033[2J\033[3J')
            sys.stdout.flush()
        try:
            return fn()
        except ConsoleBack:
            return None
        except KeyboardInterrupt:
            print()
            return None

    def main_menu(self):
        return [
            ('1', 'Status and checks', self.m_status),
            ('2', 'Live log', self.m_live_log, 'plain'),
            ('3', 'Failed attempts, logins and who is kept out', self.m_records),
            ('4', 'Banning and the whitelist', self.m_banning),
            ('5', 'The firewall and the router', self.m_firewall),
            ('6', 'Accounts of the dashboard', self.m_accounts),
            ('7', 'Settings', self.m_settings),
            ('8', 'The database and backups', self.m_backups),
            ('9', 'Network, time and power', self.m_machine),
            ('10', 'Upgrades', self.m_upgrades),
            ('11', 'The service', self.m_service),
        ]

    def run(self):
        main = self.main_menu()
        os.environ.setdefault('ESCDELAY', '25')     # Esc at once, not after a second
        # Lines and blocks drawn as UTF-8 characters, as PuTTY in UTF-8 shows
        # them - not the line-drawing set, which it draws as letters.
        os.environ.setdefault('NCURSES_NO_UTF8_ACS', '1')
        try:
            import locale
            locale.setlocale(locale.LC_ALL, '')
        except Exception:                               # noqa: BLE001
            pass
        # A terminal that is not UTF-8 is written what it can take, never a
        # character it would stop on.
        try:
            sys.stdout.reconfigure(errors='replace')
        except Exception:                               # noqa: BLE001
            pass
        import curses
        self.curses = curses

        def body(scr):
            self.scr = scr
            try:
                curses.curs_set(0)
            except Exception:                           # noqa: BLE001
                pass
            scr.keypad(True)
            self._colours()
            self.status_thread()
            # It opens on the live log, every line; Esc: the menu.
            if os.environ.get('ISEMON_CONSOLE_START', 'log') != 'menu':
                self.go_plain(lambda: self.live_log(''))
            self.menu('Main menu', main)
        try:
            curses.wrapper(body)
        except KeyboardInterrupt:
            pass
        finally:
            self.closing = True
        print(self.dim('  The isemon console is closed - `isemon --console` opens it again.'))
        return 0

    def shell(self):
        sh = os.environ.get('SHELL') or '/bin/bash'
        print(self.dim('  A shell - exit (or Ctrl+D) comes back to the isemon console.'))
        try:
            subprocess.call([sh], env=dict(os.environ, ISEMON_CONSOLE='1'))
        except (KeyboardInterrupt, OSError):
            pass

    def sub(self, title, items):
        r = self.menu(title, items, path='Main menu > ')
        return 'quit' if r == 'quit' else None

    # ---- long output: a screen of its own, scrolled ------------------------------
    # The terminal is not scrolled, a window (top) into the lines is; each
    # frame is one write (home, each line cleared to its end, the rest
    # cleared) so nothing blinks, and the scroll bar is drawn after it into
    # the last column. A window made bigger or smaller is drawn again.
    def capture(self, argv, env=None):
        """What a command writes, its colour kept: (text, exit code)."""
        e = dict(os.environ, **(env or {}))
        if self.pal.on:
            e.update(FORCE_COLOR='1', SYSTEMD_COLORS='1')
        else:
            e['NO_COLOR'] = '1'
        e['COLUMNS'] = str(max(60, self._cols() - 2))
        try:
            got = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                 stdin=subprocess.DEVNULL, env=e, timeout=1800)
            return got.stdout.decode('utf-8', 'replace'), got.returncode
        except subprocess.TimeoutExpired:
            return 'it took more than 30 minutes and was stopped', 124
        except OSError as ex:
            return str(ex), 127

    @staticmethod
    def _cols():
        try:
            return os.get_terminal_size(sys.__stdout__.fileno()).columns
        except (OSError, ValueError, AttributeError):
            return 100

    @staticmethod
    def _fit(line, width):
        """`line` cut to `width` columns on the screen, its colours kept."""
        out, seen = [], 0
        for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', line):
            if not part:
                continue
            if part.startswith('\x1b['):
                out.append(part)
                continue
            if seen + len(part) > width:
                out.append(part[:max(0, width - seen)])
                out.append('\x1b[0m')
                return ''.join(out)
            out.append(part)
            seen += len(part)
        return ''.join(out) + ('\x1b[0m' if '\x1b[' in line else '')

    def page(self, title, text):
        lines = [self._term_safe(ln.expandtabs(8), sgr=True)
                 for ln in text.rstrip('\n').split('\n')] or ['']
        if not self.pal.on:
            lines = [self._plain_text(ln) for ln in lines]
        if self._raw() is None or not sys.stdout.isatty():
            print(text)
            return
        on = self.pal.on
        out = sys.stdout
        out.write('\x1b[?1049h\x1b[?25l')
        top, size = 0, None
        try:
            while True:
                try:
                    sz = os.get_terminal_size(sys.__stdout__.fileno())
                    cols, rows = max(20, sz.columns), max(5, sz.lines)
                except OSError:
                    cols, rows = 100, 30
                avail = max(3, rows - 2)
                top = max(0, min(top, max(0, len(lines) - avail)))
                end = min(len(lines), top + avail)
                head = ' %s ' % title
                where = ' %d-%d of %d ' % (top + 1, end, len(lines)) if len(lines) > avail \
                    else ' %d lines ' % len(lines)
                bar = (head + ' ' * max(0, cols - len(head) - len(where)) + where)[:cols]
                foot = (' Up/Down PgUp/PgDn Home/End scroll   Esc, q or Enter back ')[:cols - 1]
                body = [self._fit(ln, cols - 2) for ln in lines[top:end]]
                body += [''] * (avail - len(body))
                frame = ['\x1b[7m' + bar + '\x1b[0m'] + body + \
                    ['\x1b[7m' + foot + ' ' * max(0, cols - 1 - len(foot)) + '\x1b[0m']
                out.write('\x1b[H' + '\n'.join(ln + '\x1b[K' for ln in frame) + '\x1b[J')
                self._scrollbar(2, avail, len(lines), avail, top, cols, on)
                out.flush()
                size = (cols, rows)
                while True:
                    k = self.key(0.3)
                    if k is not None:
                        break
                    try:
                        sz = os.get_terminal_size(sys.__stdout__.fileno())
                        if (max(20, sz.columns), max(5, sz.lines)) != size:
                            break
                    except OSError:
                        pass
                if k in ('esc', 'q', 'enter', 'ctrl-c', 'ctrl-d'):
                    return
                if k in ('up', 'k'):
                    top -= 1
                elif k in ('down', 'j'):
                    top += 1
                elif k in ('pgup', 'b'):
                    top -= avail - 1
                elif k in ('pgdn', ' ', 'f'):
                    top += avail - 1
                elif k in ('home', 'g'):
                    top = 0
                elif k in ('end', 'G'):
                    top = len(lines)
        finally:
            out.write('\x1b[?25h\x1b[?1049l')
            out.flush()

    def _scrollbar(self, base_row, nrows, total, visible, top, cols, on=True):
        if total <= visible or nrows <= 0:
            return
        thumb = max(1, min(nrows, round(nrows * visible / total)))
        span = nrows - thumb
        denom = max(1, total - visible)
        tstart = max(0, min(span, round(span * (top / denom))))
        utf = self.utf()
        parts = ['\x1b[?7l']
        for r in range(nrows):
            hit = tstart <= r < tstart + thumb
            g = ('█' if hit else '│') if utf else ('#' if hit else '|')
            if on:
                g = ('\x1b[36m' if hit else '\x1b[2m') + g + '\x1b[0m'
            parts.append('\x1b[%d;%dH%s' % (base_row + r, cols, g))
        parts.append('\x1b[?7h')
        sys.stdout.write(''.join(parts))

    def show_live(self, *args, env=None):
        """`isemon ARGS` straight on the terminal - one that asks something, or
        shows its progress as it goes."""
        if any(a is None or str(a).strip() == '' for a in args):
            return
        self.clear_screen()
        gone = self.missing(args)
        print(self.dim(self.shown(args)))
        if gone:
            print(self.pal.warn_text('  %s is not in this version (isemon %s)' % (gone,
                                                                                 __version__)))
        else:
            try:
                subprocess.call(self.base() + [str(a) for a in args]
                                + ([] if self.pal.on else ['--no-color']),
                                env=dict(os.environ, **(env or {})))
            except KeyboardInterrupt:
                print()
        self.pause()

    # ---- live views: scrolled, and what is typed is a grep ------------------------
    # The log and the journal come into one screen of their own: the newest at
    # the bottom, followed while the view is at the end. Up/PgUp/Home scroll
    # back (the view then stays where it is and counts what came meanwhile),
    # End follows again; a bar on the right shows where the window is.
    # Whatever is typed filters the lines as `grep -i` does (a regular
    # expression, or the words as they are when it is not one), the hits
    # marked; Backspace takes a character back, Ctrl+U all of them. Esc
    # clears the filter first, then goes back to the menu.
    @staticmethod
    def log_path():
        """Where the daemon writes its log: the one it opened, where this is
        the daemon, or the one it opens."""
        return Path(_LOG_PATH) if _LOG_PATH else (Path(LOG_DIR) / 'isemon.log')

    def m_live_log(self):
        return self.live_log('')

    @staticmethod
    def _log_open(path):
        """The log, opened as root opens a file of the isemon account's
        (1.10.234): a link is not followed, a FIFO does not hold the login up,
        and anything but a plain file is not read."""
        fd = os.open(str(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            os.close(fd)
            raise OSError('it is not a plain file')
        return os.fdopen(fd, 'r', encoding='utf-8', errors='replace')

    def live_log(self, what=''):
        path = self.log_path()
        st = {'f': None, 'ino': None}

        def first():
            try:
                f = self._log_open(path)
            except OSError as e:
                return ['%s cannot be read: %s' % (path, e)]
            st['f'] = f
            st['ino'] = os.fstat(f.fileno()).st_ino
            # Read from near the end only: a log can be gigabytes.
            f.seek(0, 2)
            start = max(0, f.tell() - 2 * 1024 * 1024)
            f.seek(start)
            got = f.read(2 * 1024 * 1024).splitlines()
            # A line cut in two by where the reading began is left out.
            return (got[1:] if start and len(got) > 1 else got)[-self.LIVE_KEEP:]

        def more():
            f = st['f']
            if f is None:
                return []
            out = []
            while len(out) < 5000:
                ln = f.readline(65536)
                if not ln:
                    break
                out.append(ln.rstrip('\n'))
            if not out:
                try:
                    if os.stat(str(path)).st_ino != st['ino']:      # rotated
                        f.close()
                        st['f'] = None
                        st['f'] = self._log_open(path)
                        st['ino'] = os.fstat(st['f'].fileno()).st_ino
                except OSError:
                    pass
            return out
        try:
            self.live_view('Live log  %s' % path, first, more, self.log_text, what)
        finally:
            if st['f']:
                st['f'].close()

    def journal(self):
        """journalctl -u isemon -f, in the live view."""
        try:
            pr = subprocess.Popen([CONSOLE_JOURNALCTL, '-u', 'isemon', '-f', '-n', '400',
                                   '--no-pager'], stdout=subprocess.PIPE,
                                  stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL,
                                  text=True, errors='replace')
        except OSError as e:
            self.page('journalctl', str(e))
            return
        q = collections.deque()

        def pump():
            for ln in pr.stdout:
                q.append(ln.rstrip('\n'))
        threading.Thread(target=pump, daemon=True).start()

        def more():
            out = []
            while q:
                out.append(q.popleft())
            return out

        def paint(ln):
            # The journal's own head (when, where, who), then the log's line.
            m = re.match(r'^(\S+ +\d+ [\d:]+ \S+ \S+: )(.*)$', ln)
            if m:
                return self.dim(m.group(1)) + self.log_text(m.group(2))
            return self.log_text(ln)
        try:
            self.live_view('journalctl -u isemon -f', lambda: [], more, paint, '')
        finally:
            pr.terminate()
            try:
                pr.wait(3)
            except Exception:                           # noqa: BLE001
                pr.kill()

    @staticmethod
    def grep(find):
        """What is typed as `grep -i` takes it: a test of one line."""
        if not find:
            return lambda s: True
        try:
            rx = re.compile(find, re.I)
            return lambda s: rx.search(s) is not None
        except re.error:
            low = find.lower()
            return lambda s: low in s.lower()

    def mark(self, coloured, find):
        """The hits of `find` shown reversed - in the text between the colours."""
        if not find or not self.pal.on:
            return coloured
        try:
            rx = re.compile(find, re.I)
        except re.error:
            rx = re.compile(re.escape(find), re.I)
        out = []
        for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', coloured):
            if part.startswith('\x1b['):
                out.append(part)
            elif part:
                out.append(rx.sub(lambda m: '\x1b[7m' + m.group(0) + '\x1b[27m'
                                  if m.group(0) else '', part))
        return ''.join(out)

    @staticmethod
    def _slice(line, start, width):
        """Columns start..start+width of `line` on the screen, its colours kept."""
        out, seen = [], 0
        end = start + width
        for part in re.split(r'(\x1b\[[0-9;?]*[A-Za-z])', line):
            if not part:
                continue
            if part.startswith('\x1b['):
                out.append(part)
                continue
            a, b = seen, seen + len(part)
            if b > start and a < end:
                out.append(part[max(0, start - a):max(0, end - a)])
            seen = b
        return ''.join(out) + ('\x1b[0m' if '\x1b[' in line else '')

    def live_view(self, title, first, more, paint, find=''):
        """The live screen: `first()` the lines there are, `more()` those come
        since (asked a few times a second), `paint(line)` its colours."""
        p = self.pal
        if self._raw() is None or not sys.stdout.isatty():
            for ln in first() + more():
                print(ln)
            return
        import termios
        import tty
        fd = sys.stdin.fileno()
        was = termios.tcgetattr(fd)
        out = sys.stdout
        lines = []                       # (plain, coloured)

        def add(raw):
            for ln in raw:
                ln = self._term_safe(ln.expandtabs(8))
                col = (paint(ln) if paint else ln) if p.on else self._plain_text(ln)
                lines.append((self._plain_text(col), col))
        add(first())
        test = self.grep(find)
        hits = [i for i, x in enumerate(lines) if test(x[0])]
        top, follow, xoff, new, dirty, size = 0, True, 0, 0, True, None
        tty.setcbreak(fd, termios.TCSANOW)
        out.write('\x1b[?1049h\x1b[?25l')
        try:
            while True:
                came = more()
                if came:
                    n0 = len(lines)
                    add(came)
                    got = [i for i in range(n0, len(lines)) if test(lines[i][0])]
                    hits += got
                    if not follow:
                        new += len(got)
                    if len(lines) > self.LIVE_KEEP * 1.25:
                        cut = len(lines) - self.LIVE_KEEP
                        gone = sum(1 for i in hits if i < cut)
                        del lines[:cut]
                        hits = [i - cut for i in hits if i >= cut]
                        top = max(0, top - gone)
                    dirty = dirty or bool(got)
                try:
                    sz = os.get_terminal_size(sys.__stdout__.fileno())
                    cols, rows = max(20, sz.columns), max(5, sz.lines)
                except OSError:
                    cols, rows = 100, 30
                if (cols, rows) != size:
                    size, dirty = (cols, rows), True
                avail = max(3, rows - 2)
                last = max(0, len(hits) - avail)
                if follow:
                    top = last
                top = max(0, min(top, last))
                if dirty:
                    end = min(len(hits), top + avail)
                    where = (' %d-%d of %d ' % (top + 1, end, len(hits))) if hits else ' 0 '
                    state = ' following ' if follow else (' PAUSED%s ' % (
                        ', %d new below' % new if new else ''))
                    head = ' %s ' % title
                    gp = '  grep -i: %s_ ' % find if find else '  type to grep '
                    right = state + where
                    bar = (head + gp)[:max(0, cols - len(right))]
                    bar = bar + ' ' * max(0, cols - len(bar) - len(right)) + right
                    foot = (' type: grep (any case)  Bksp  Ctrl+U clear   Up/Down PgUp/PgDn '
                            'Home  End: follow   Left/Right  Esc back ')[:cols - 1]
                    body = [self._slice(self.mark(lines[i][1], find), xoff, cols - 2)
                            for i in hits[top:end]]
                    if not hits:
                        body = ['', '   ' + (self.dim('nothing with "%s" yet' % find) if find
                                             else self.dim('nothing yet'))]
                    body += [''] * (avail - len(body))
                    tone = '\x1b[33m' if (not follow and p.on) else ''
                    frame = [tone + '\x1b[7m' + bar[:cols] + '\x1b[0m'] + body[:avail] + \
                        ['\x1b[7m' + foot + ' ' * max(0, cols - 1 - len(foot)) + '\x1b[0m']
                    out.write('\x1b[H' + '\n'.join(ln + '\x1b[K' for ln in frame) + '\x1b[J')
                    self._scrollbar(2, avail, len(hits), avail, top, cols, p.on)
                    out.flush()
                    dirty = False
                k = self.key(0.25)
                if k is None:
                    continue
                dirty = True
                if k in ('esc', 'ctrl-c', 'ctrl-d'):
                    if find and k == 'esc':
                        find = ''
                    else:
                        return
                elif k == 'up':
                    follow, top = False, top - 1
                elif k == 'down':
                    top += 1
                    follow = top >= last
                elif k == 'pgup':
                    follow, top = False, top - (avail - 1)
                elif k == 'pgdn':
                    top += avail - 1
                    follow = top >= last
                elif k == 'home':
                    follow, top = False, 0
                elif k in ('end', 'enter'):
                    follow, new = True, 0
                elif k == 'left':
                    xoff = max(0, xoff - 20)
                    continue
                elif k == 'right':
                    xoff += 20
                    continue
                elif k == 'bs':
                    find = find[:-1]
                elif k == 'ctrl-u':
                    find = ''
                elif k and len(k) == 1 and k.isprintable():
                    find += k
                else:
                    continue
                if k in ('bs', 'ctrl-u', 'esc') or (k and len(k) == 1 and k.isprintable()):
                    test = self.grep(find)
                    hits = [i for i, x in enumerate(lines) if test(x[0])]
                    follow, new = True, 0
                if follow:
                    new = 0
        finally:
            out.write('\x1b[?25h\x1b[?1049l')
            out.flush()
            termios.tcsetattr(fd, termios.TCSADRAIN, was)

    RE_LOG_LINE = re.compile(r'^(\d{2}-\d{2}-\d{4} \d{2}:\d{2}:\d{2}) \[(\w+)\](\s+)(.*)$')

    def log_text(self, ln):
        """One line of the log, coloured: the time dim, the level by how bad,
        what it is about in cyan, addresses in magenta, banned and refused in
        red, let back in and signed in in green, a whole warning in yellow
        and a whole error in red. Only colour is added - taken off again the
        line is exactly what was in the file, column for column."""
        p = self.pal
        ln = ln.rstrip('\n')
        m = self.RE_LOG_LINE.match(ln)
        if not m or not p.on:
            return ln
        lvl, gap, rest = m.group(2), m.group(3), m.group(4)
        tone = self.LOG_TONES.get(lvl, '')
        whole = {'bad': p.c_bad, 'warn': p.c_warn, 'dim': p.dim}.get(tone, '')
        what = re.match(r'^([a-z][a-z0-9 _/-]{1,30}): (.*)$', rest)
        head, body = (what.group(1) + ':', what.group(2)) if what else ('', rest)

        def back():
            return p.off + whole

        def words(t):
            t = re.sub(r'(?<![\w.:])(\d{1,3}(?:\.\d{1,3}){3}(?:/\d{1,2})?|'
                       r'[0-9a-fA-F]{1,4}(?::[0-9a-fA-F]{0,4}){2,7}(?:/\d{1,3})?)(?![\w.:])',
                       lambda x: p.c_addr + x.group(1) + back(), t)
            t = re.sub(r'\b(let back in|let in|signed in|accepted|unbanned|synced|saved|ok)\b',
                       lambda x: p.c_ok + x.group(1) + back(), t)
            t = re.sub(r'\b(banned|refused|rejected|failed|wrong|cannot|not answering)\b',
                       lambda x: p.c_bad + x.group(1) + back(), t)
            return t
        body = whole + words(body) + (p.off if whole else '')
        lv = (whole or p.c_info) + '[' + lvl + ']' + p.off
        return '%s %s%s%s%s' % (self.dim(m.group(1)), lv, gap,
                                (p.c_info + head + p.off + ' ') if head else '', body)

    # ---- 1 status -------------------------------------------------------------------
    def m_status(self):
        def events():
            got = self.form('Events', [
                {'key': 'n', 'label': 'how many', 'kind': 'number', 'value': '40',
                 'range': (1, 5000), 'need': True},
                {'key': 'q', 'label': 'only with the words', 'help':
                 'Empty: every event. Or a name, an address or a word.'}])
            if got:
                self.act('--events', '--limit', got['n'],
                         *(['--search', got['q']] if got['q'] else []))

        def stop_job():
            got = self.out('--jobs') or {}
            jobs = self._rows(got, 'jobs', 'rows')
            going = [j for j in jobs if isinstance(j, dict) and not j.get('done')]
            if not going:
                self.note('Stop a long job', 'No long job is going on.')
                return
            name = self.choose('Stop a long job', [
                (str(j.get('id') or j.get('kind')), '%s  %s' % (j.get('id') or '',
                                                                 j.get('kind') or ''))
                for j in going], 'It stops after the batch it is in and keeps what it has '
                'already done.')
            if name and self.confirm('Stop a long job', 'The job %s stops after the batch it '
                                     'is in.' % name, 'Stop it'):
                self.act('--stop-job', name)
        return self.sub('Status and checks', [
            ('1', 'Status', lambda: self.act('--status')),
            ('2', 'Status, every log file on a line of its own',
             lambda: self.act('--status', '--files')),
            ('3', 'Health check', lambda: self.act('--check')),
            ('4', 'Long jobs going on', lambda: self.act('--jobs')),
            ('5', 'Stop a long job', stop_job),
            ('6', 'Events of the daemon', events),
            ('7', 'What root has in place (nginx, TLS, the firewall)',
             lambda: self.act('--web-status')),
        ])

